window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[99]={"id":"099","numero":99,"titre":"Céphalée · Migraine · AVF · Névralgies craniofaciales","objectifs":[{"id":"99-1","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie des céphalées et douleurs de la face","contenu":"<p>Les <span class=\"kw-def\"><strong>céphalées et douleurs de la face</strong></span> regroupent <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> g</span>randes entités à connaître : migraine (la plus fréquente), <span class=\"kw-clinique\">céphalée</span> de tension, AVF et névralgie du trijumeau. Les douleurs faciales (sous le plan orbito-méatale) touchent <span class=\"kw-chiffre\">8 à 10 %</span> de la population générale, d'origine <span class=\"kw-etio\">dentaire</span> dans la majorité des cas.</p>\n      <table >\n        <thead><tr><th>Entité</th><th><span class=\"kw-def\">Prévalence</span></th><th>Sex-ratio</th><th>Âge typique</th><th>FR principal</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Migraine</strong></span></td>\n            <td><span class=\"kw-chiffre\">14,5 %</span> (1 milliard dans le monde) ; MSA <span class=\"kw-chiffre\">6-10 %</span> ; MA <span class=\"kw-chiffre\">3-6 %</span> ; chronique <span class=\"kw-chiffre\">1,7 %</span></td>\n            <td>féminin <span class=\"kw-chiffre\">3F/1H</span> (post-puberté)</td>\n            <td><span class=\"kw-chiffre\">20-50 ans</span> (pic <span class=\"kw-chiffre\">35-40 ans</span>) ; <span class=\"kw-chiffre\">90 %</span> début &lt;<span class=\"kw-chiffre\"> 40 ans</span> ; rare &gt;<span class=\"kw-chiffre\"> 65 ans</span></td>\n            <td><span class=\"kw-etio\">Hérédité</span> (<span class=\"kw-chiffre\">40-50 g</span>ènes), <span class=\"kw-etio\">œstrogènes</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Céphalée de tension</strong></span></td>\n            <td><span class=\"kw-chiffre\">30 à 80 %</span> — <span class=\"kw-clinique\">céphalée</span> primaire la plus fréquente</td>\n            <td>féminin <span class=\"kw-chiffre\">3F/2H</span></td>\n            <td>début à l'adolescence</td>\n            <td><span class=\"kw-etio\">Stress</span>, <span class=\"kw-etio\">contractions musculaires</span> péri-crâniennes</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Algie vasculaire de la face</strong></span></td>\n            <td><span class=\"kw-chiffre\">1/1000</span> (<span class=\"kw-chiffre\">0,1 %</span>) — <span class=\"kw-clinique\">céphalée</span> primaire rare</td>\n            <td>masculin <span class=\"kw-chiffre\">5H/1F</span></td>\n            <td><span class=\"kw-chiffre\">30 ans</span> (exceptionnelle &lt;<span class=\"kw-chiffre\"> 10 ans</span>)</td>\n            <td><span class=\"kw-etio\">Tabac</span> (<span class=\"kw-chiffre\">80 %</span>), <span class=\"kw-etio\">alcool</span> (déclenchant)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Névralgie du trijumeau</strong></span></td>\n            <td><span class=\"kw-chiffre\">5/100 000/an</span></td>\n            <td>féminin <span class=\"kw-chiffre\">3F/2H</span></td>\n            <td><span class=\"kw-clinique\">&gt; 50-60 ans</span> (<span class=\"kw-def\">incidence</span> ↑ avec l'âge)</td>\n            <td><span class=\"kw-etio\">Conflit vasculo-nerveux</span> à l'angle pontocérébelleux</td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Donnée clé — Migraine</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Maladie neurologique</strong></td><td>la plus <span class=\"kw-alerte\">invalidante</span> selon l'OMS</td></tr>\n          <tr><td><strong>Enfant prépubère</strong></td><td><span class=\"kw-chiffre\">7 %</span> sans différence entre sexes — <span class=\"kw-clinique\">1ʳᵉ cause de céphalées récurrentes chez l'enfant</span> (sex-ratio se fait après la puberté)</td></tr>\n          <tr><td><strong>Migraine avec aura</strong></td><td><span class=\"kw-alerte\">FR indépendant d'infarctus cérébral</span> (RR ×2) — surrisque <span class=\"kw-alerte\">femme &lt; 45 ans + tabac + COP</span></td></tr>\n          <tr><td><strong>Caractère familial</strong></td><td>souvent retrouvé — plus le début est précoce, plus la part <span class=\"kw-etio\">génétique</span> est importante</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Évolution</span></strong></td><td>diminution avec l'âge, arrêt vers <span class=\"kw-chiffre\">55 ans</span> ; chronicisation <span class=\"kw-chiffre\">2-3 %/an</span> des MSA</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Point pivot.</strong> La <span class=\"kw-def\">migraine avec aura</span> est un <span class=\"kw-alerte\">FR indépendant d'AVC ischémique</span>, particulièrement chez la femme &lt;<span class=\"kw-chiffre\"> 45 ans</span> tabagique ou sous COP — d'où la <span class=\"kw-ci\">contre-indication absolue de la COP</span> dans cette population (cf. obj-15).</div>","frequence":1},{"id":"99-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les bases physiopathologiques de la migraine","contenu":"<p>La migraine est une <span class=\"kw-def\">pathologie neurovasculaire de l'adaptation aux changements</span>, sous-tendue par une <span class=\"kw-def\">hyperexcitabilité cérébrale héréditaire</span> et une <span class=\"kw-def\">dysfonction des centres modulateurs de la nociception céphalique</span> (hypothalamus, tronc cérébral). <span class=\"kw-chiffre\">40 à 50 gènes</span> de susceptibilité connus.</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Mécanisme</th><th>Signes / Conséquences</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Prodromes</strong></span></td>\n            <td><span class=\"kw-clinique\">Hyperactivité hypothalamique</span> (visible en imagerie fonctionnelle, jusqu'à <span class=\"kw-chiffre\">72 h</span>) + <span class=\"kw-clinique\">dysfonction du système nerveux végétatif</span> → levée d'inhibition du tronc cérébral et du système trigémino-vasculaire</td>\n            <td>Fringale (chocolat, gâteaux), bâillements, <span class=\"kw-ci\">hypersensibilité</span> sensorielle, troubles humeur, troubles concentration</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Aura</strong></span></td>\n            <td><span class=\"kw-def\">Dépression corticale envahissante (DCE)</span> — vague qui se propage d'arrière en avant à <span class=\"kw-chiffre\">3-5 mm/min</span> ; <strong>biphasique</strong> : courte phase d'<span class=\"kw-clinique\">hyperactivité neuronale + hyperperfusion</span>, puis phase prolongée d'<span class=\"kw-clinique\">hypoactivité neuronale + hypoperfusion modérée</span> n'atteignant <span class=\"kw-alerte\">pas le seuil ischémique</span></td>\n            <td>Symptômes neurologiques transitoires (visuels, sensitifs, parole) selon les zones traversées ; concerne les sujets à <span class=\"kw-etio\">susceptibilité génétique spécifique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Céphalée</strong></span></td>\n            <td><span class=\"kw-def\">Activation du système trigémino-vasculaire</span> : V1 innerve vaisseaux intracrâniens et méninges → libération de <span class=\"kw-ttt\">CGRP</span> et autres neuropeptides → <span class=\"kw-clinique\">inflammation aseptique péri-vasculaire et méningée</span> + vasodilatation modérée ; <span class=\"kw-alerte\">hypersensibilité au CGRP</span> chez le migraineux</td>\n            <td>Message douloureux V1 → noyau caudal du V dans le tronc cérébral → convergence avec C2 (<span class=\"kw-clinique\">céphalée</span> + face + cou) → 2ᵉ neurone vers thalamus ; sensibilisation centrale → <span class=\"kw-clinique\">allodynie cutanée</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Post-dromes</strong></span></td>\n            <td>Rétablissement progressif de l'<span class=\"kw-def\">homéostasie cérébrale</span></td>\n            <td>Fatigue, troubles digestifs résiduels</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Phase interictale</strong></span></td>\n            <td>Durée variable selon l'efficacité des systèmes de contrôle du réflexe trigémino-vasculaire et des voies de la nociception</td>\n            <td>Dans les formes sévères / chroniques : <span class=\"kw-clinique\">photophobie</span>, <span class=\"kw-clinique\">phonophobie</span>, <span class=\"kw-clinique\">osmophobie</span> et <span class=\"kw-clinique\">allodynie permanente</span> qui s'aggravent en prodromes</td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 470\" role=\"img\" aria-label=\"Frise des bases physiopathologiques de la migraine en cinq phases successives, mémo P-A-C-P-I. Phase un, prodromes : hyperactivité de l'hypothalamus visible jusqu'à 72 heures avant la céphalée, qui lève l'inhibition du tronc cérébral et du système trigémino-vasculaire. Phase deux, aura : vague de dépression corticale envahissante qui se propage d'arrière en avant à 3 à 5 millimètres par minute, biphasique, sans atteindre le seuil ischémique. Phase trois, céphalée : activation du système trigémino-vasculaire avec libération de CGRP et inflammation aseptique péri-vasculaire et méningée. Phase quatre, post-dromes : rétablissement progressif de l'homéostasie cérébrale. Phase cinq, phase interictale : intervalle libre de durée variable selon les systèmes de contrôle de la nociception.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\">Migraine — 5 phases (mémo P-A-C-P-I)</text>\n\n          <rect class=\"fb-amber\" x=\"60\" y=\"36\" width=\"440\" height=\"56\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"280\" y=\"58\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">1. Prodromes — hyperactivité hypothalamique</text>\n          <text class=\"tx-amber\" x=\"280\" y=\"75\" text-anchor=\"middle\" font-size=\"10.5\">jusqu'à<span class=\"kw-chiffre\"> 72 h</span> avant · lève l'inhibition du tronc + trigémino-vasculaire</text>\n          <line class=\"ln\" x1=\"280\" y1=\"92\" x2=\"280\" y2=\"108\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,114 275,106 285,106\"/>\n\n          <rect class=\"fb-amber\" x=\"60\" y=\"116\" width=\"440\" height=\"58\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"280\" y=\"138\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">2. Aura — dépression corticale envahissante (DCE)</text>\n          <text class=\"tx-amber\" x=\"280\" y=\"155\" text-anchor=\"middle\" font-size=\"11\">propagation d'arrière en avant à<span class=\"kw-chiffre\"> 3–5 mm</span>/min · biphasique</text>\n          <text class=\"tx-amber\" x=\"280\" y=\"169\" text-anchor=\"middle\" font-size=\"10.5\">n'atteint PAS le seuil <span class=\"kw-etio\">ischémique</span> (≠ <span class=\"kw-alerte\">AIT</span>)</text>\n          <line class=\"ln\" x1=\"280\" y1=\"174\" x2=\"280\" y2=\"190\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,196 275,188 285,188\"/>\n\n          <rect class=\"fb-red\" x=\"60\" y=\"198\" width=\"440\" height=\"58\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"280\" y=\"220\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">3. <span class=\"kw-clinique\">Céphalée</span> — système trigémino-vasculaire</text>\n          <text class=\"tx-red\" x=\"280\" y=\"237\" text-anchor=\"middle\" font-size=\"11\">libération de CGRP · inflammation aseptique péri-vasculaire</text>\n          <text class=\"tx-red\" x=\"280\" y=\"251\" text-anchor=\"middle\" font-size=\"10.5\">et méningée · sensibilisation centrale → allodynie</text>\n          <line class=\"ln\" x1=\"280\" y1=\"256\" x2=\"280\" y2=\"272\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,278 275,270 285,270\"/>\n\n          <rect class=\"fb-ok\" x=\"60\" y=\"280\" width=\"440\" height=\"52\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"280\" y=\"302\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">4. Post-dromes</text>\n          <text class=\"tx-ok\" x=\"280\" y=\"319\" text-anchor=\"middle\" font-size=\"11\">rétablissement progressif de l'homéostasie cérébrale</text>\n          <line class=\"ln\" x1=\"280\" y1=\"332\" x2=\"280\" y2=\"348\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,354 275,346 285,346\"/>\n\n          <rect class=\"fb-grey\" x=\"60\" y=\"356\" width=\"440\" height=\"58\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"280\" y=\"378\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">5. Phase interictale</text>\n          <text class=\"tx-grey\" x=\"280\" y=\"395\" text-anchor=\"middle\" font-size=\"11\">intervalle libre · durée selon les systèmes de contrôle</text>\n          <text class=\"tx-grey\" x=\"280\" y=\"409\" text-anchor=\"middle\" font-size=\"10.5\">de la nociception (photo/phono/osmophobie si formes sévères)</text>\n\n          <text class=\"tx-muted\" x=\"280\" y=\"438\" text-anchor=\"middle\" font-size=\"10.5\"><span class=\"kw-def\">Terrain</span> : hyperexcitabilité cérébrale <span class=\"kw-etio\">héréditaire</span> (<span class=\"kw-chiffre\">40–50 g</span>ènes)</text>\n          <text class=\"tx-muted\" x=\"280\" y=\"456\" text-anchor=\"middle\" font-size=\"10.5\">+ dysfonction des centres modulateurs de la nociception céphalique</text>\n        </svg>\n        <figcaption>Cascade physiopathologique de la migraine en 5 phases (P-A-C-P-I). La DCE de l'aura n'atteint pas le seuil ischémique, ce qui la distingue de l'<span class=\"kw-alerte\">AIT</span>. Source : fiche source EDN item 99 — Migraine.</figcaption>\n      </figure>\n      <div class=\"callout callout-info\"><strong>Mémo.</strong> 5 phases = <strong>P-A-C-P-I</strong> : <span class=\"kw-def\">Prodromes</span> (hypothalamus) → <span class=\"kw-def\">Aura</span> (DCE) → <span class=\"kw-def\">Céphalée</span> (CGRP, inflammation) → <span class=\"kw-def\">Post-dromes</span> → <span class=\"kw-def\">Interictale</span>. La <span class=\"kw-clinique\">DCE</span> n'atteint pas le seuil <span class=\"kw-etio\">ischémique</span> : c'est ce qui distingue l'aura migraineuse de l'<span class=\"kw-def\">AIT</span>.</div>\n      <div class=\"callout callout-warn\"><strong>Exception <span class=\"kw-etio\">génétique</span>.</strong> La <span class=\"kw-etio\">migraine hémiplégique familiale</span> = <span class=\"kw-def\">canalopathie</span> autosomique dominante (mutation de gènes codant des transporteurs ioniques) ; l'aura motrice y est la traduction clinique. À distinguer des migraines communes polygéniques.</div>","frequence":0},{"id":"99-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d'une céphalée primaire","contenu":"<p>Le diagnostic d'une <span class=\"kw-def\">céphalée primaire</span> repose sur les <span class=\"kw-def\">critères cliniques ICHD-3</span> et l'<span class=\"kw-def\">élimination d'une céphalée secondaire</span>. <strong>Règle d'or :</strong> toute <span class=\"kw-clinique\">céphalée</span> évoluant par crises depuis <span class=\"kw-chiffre\">&gt; 3 mois</span> est une migraine jusqu'à preuve du contraire ; toute céphalée chronique quotidienne &gt;<span class=\"kw-chiffre\"> 3 mois</span> est une <span class=\"kw-etio\">migraine chronique</span> jusqu'à preuve du contraire.</p>\n      <table >\n        <thead><tr><th>Céphalée primaire</th><th>Latéralité</th><th>Durée crise</th><th>Caractère</th><th>Signes associés</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Migraine</strong></span></td>\n            <td><span class=\"kw-clinique\">Unilatérale à bascule</span> (peut être bilat enfant)</td>\n            <td><span class=\"kw-chiffre\">4 à 72 h</span> (adulte) ; <span class=\"kw-chiffre\">2-4 h</span> (enfant)</td>\n            <td><span class=\"kw-clinique\">Pulsatile</span>, modérée à sévère, aggravée par l'effort</td>\n            <td><span class=\"kw-clinique\">Nausées/vomissements</span>, <span class=\"kw-clinique\">photophobie + phonophobie</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Céphalée de tension</strong></span></td>\n            <td><span class=\"kw-clinique\">Bilatérale</span> (barre frontale ou cervicale)</td>\n            <td><span class=\"kw-chiffre\">30 min à 7 j</span></td>\n            <td><span class=\"kw-clinique\">Serrement / étau / pression</span>, légère à modérée</td>\n            <td><span class=\"kw-clinique\">Aucun</span> ; sensibilité musculaire péri-crânienne ; améliorée par activité ou repos</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>AVF</strong></span></td>\n            <td><span class=\"kw-clinique\">Unilatérale STRICTE</span> (toujours du même côté)</td>\n            <td><span class=\"kw-chiffre\">15 à 180 min</span> (acmé en <span class=\"kw-chiffre\">10-15 min</span>)</td>\n            <td><span class=\"kw-clinique\">Broiement / arrachement</span>, péri-orbitaire, très sévère</td>\n            <td><span class=\"kw-clinique\">Dysautonomiques homolatéraux</span> (larmoiement, injection, rhinorrhée, ptosis/myosis), <span class=\"kw-clinique\">agitation/impatience</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Névralgie du V</strong></span></td>\n            <td><span class=\"kw-clinique\">Unilatérale</span> dans le territoire V (surtout V2)</td>\n            <td>Salves <span class=\"kw-chiffre\">≤ 2 min</span> ; <span class=\"kw-chiffre\">5-10/jour</span></td>\n            <td><span class=\"kw-clinique\">Éclair / décharge électrique</span>, fulgurante, déclenchée par <span class=\"kw-clinique\">zone gâchette</span></td>\n            <td><span class=\"kw-clinique\">Examen normal</span> entre les crises ; aucun signe associé</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeaux rouges</span> — <span class=\"kw-clinique\">céphalée</span> secondaire à dépister systématiquement.</strong>\n        <ul>\n          <li>Début <span class=\"kw-alerte\">brutal</span> ou en <span class=\"kw-alerte\">coup de tonnerre</span> (HSA, <span class=\"kw-etio\">dissection</span>, <span class=\"kw-def\">AVC</span>)</li>\n          <li><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-alerte\">récente + aggravation progressive &lt; 7 j</span> (TVC, processus expansif)</li>\n          <li><span class=\"kw-alerte\">Fièvre</span> associée (<span class=\"kw-def\">méningite</span>, <span class=\"kw-clinique\">abcès</span>)</li>\n          <li><span class=\"kw-alerte\">Signes neurologiques</span> associés (déficit focal, BAV, <span class=\"kw-clinique\">confusion</span>, somnolence)</li>\n          <li>Caractéristiques d'<span class=\"kw-alerte\">intoxication au CO</span></li>\n          <li><span class=\"kw-alerte\">Contexte d'immunodépression</span></li>\n          <li><span class=\"kw-alerte\">Âge &gt; 50 ans</span> à l'apparition (Horton, processus expansif)</li>\n          <li><span class=\"kw-alerte\">Modification</span> d'une <span class=\"kw-clinique\">céphalée</span> préexistante</li>\n          <li>Caractère <span class=\"kw-alerte\">orthostatique</span> (hypoTA intra-crânienne)</li>\n          <li>Déclenchement par <span class=\"kw-alerte\">Valsalva</span>, <span class=\"kw-clinique\">toux</span> (<span class=\"kw-alerte\">HTIC</span>)</li>\n          <li><span class=\"kw-alerte\">Œdème papillaire</span> au <span class=\"kw-imagerie\">FO</span>, <span class=\"kw-alerte\">PA très élevée</span>, douleur des artères temporales</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalée</span></em></p>","frequence":2},{"id":"99-4","rang":"A","rubrique":"Diagnostic positif","titre":"Conduire l'interrogatoire et réunir les arguments du diagnostic de migraine (avec ou sans aura)","contenu":"<p>Le diagnostic de migraine repose sur les <span class=\"kw-def\">critères ICHD-3</span> et un <span class=\"kw-clinique\">examen neurologique normal</span>. <strong>Mémo MSA :</strong> <span class=\"kw-chiffre\">5-4-3-2-1</span> (<span class=\"kw-chiffre\">≥ 5</span> crises, <span class=\"kw-chiffre\">4-72 h</span>, <span class=\"kw-chiffre\">≥ 2</span> caractéristiques, <span class=\"kw-chiffre\">≥ 1</span> signe associé).</p>\n      <table >\n        <thead><tr><th>Critère ICHD-3 — Migraine sans aura (MSA)</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A.</strong></td><td><span class=\"kw-chiffre\">≥ 5 crises</span> répondant aux critères B-D</td></tr>\n          <tr><td><strong>B. Durée</strong></td><td><span class=\"kw-chiffre\">4 à 72 h</span> (si non traitées ou traitement inefficace) — <span class=\"kw-clinique\">2-4 h chez l'enfant</span></td></tr>\n          <tr>\n            <td><strong>C. <span class=\"kw-chiffre\">≥ 2</span>/4 caractéristiques</strong></td>\n            <td>\n              <strong>Latéralité :</strong> unilatérale<br>\n              <strong>Type :</strong> pulsatile<br>\n              <strong>Intensité :</strong> modérée à sévère<br>\n              <strong>Aggravation :</strong> par les activités physiques de routine (<span class=\"kw-clinique\">marche, escalier</span>) ou évitement de celles-ci\n            </td>\n          </tr>\n          <tr>\n            <td><strong>D. <span class=\"kw-chiffre\">≥ 1</span>/2 signes</strong></td>\n            <td>\n              <strong>Digestif :</strong> <span class=\"kw-clinique\">nausées</span> <span class=\"kw-clinique\">et/ou</span> <span class=\"kw-clinique\">vomissements</span><br>\n              <strong>Sensoriel :</strong> photophobie <span class=\"kw-clinique\">ET</span> phonophobie\n            </td>\n          </tr>\n          <tr><td><strong>E.</strong></td><td>Pas mieux expliqué par un autre diagnostic ICHD-3</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Critère ICHD-3 — Migraine avec aura (MA)</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A.</strong></td><td><span class=\"kw-chiffre\">≥ 2 crises</span> répondant aux critères B-C</td></tr>\n          <tr>\n            <td><strong>B. Auras typiques (les seules acceptables sans bilan)</strong></td>\n            <td>\n              <strong>Visuelles</strong> (les plus fréquentes, <span class=\"kw-chiffre\">99 %</span>) ;<br>\n              <strong>Sensitives</strong> (<span class=\"kw-chiffre\">30 %</span>) ;<br>\n              <strong>Parole ou langage</strong> (<span class=\"kw-chiffre\">20 %</span>)<br>\n              <span class=\"kw-ci\">PAS d'aura motrice, basilaire ou rétinienne</span> sans bilan complémentaire\n            </td>\n          </tr>\n          <tr>\n            <td><strong>C. <span class=\"kw-chiffre\">≥ 3</span>/6 caractéristiques</strong></td>\n            <td>\n              <span class=\"kw-chiffre\">≥ 1</span> symptôme se développe progressivement en <span class=\"kw-chiffre\">≥ 5 min</span> ;<br>\n              si plusieurs symptômes : surviennent successivement ;<br>\n              chaque symptôme dure <span class=\"kw-chiffre\">5 à 60 min</span> ;<br>\n              ≥ 1 symptôme unilatéral ;<br>\n              ≥ 1 symptôme positif (déficitaire ou productif) ;<br>\n              <span class=\"kw-clinique\">céphalée</span> accompagne ou survient <span class=\"kw-chiffre\">&lt; 1 h</span> après l'aura\n            </td>\n          </tr>\n          <tr><td><strong>D.</strong></td><td>Pas mieux expliqué par autre diagnostic ICHD-3 et <span class=\"kw-alerte\">AIT exclu</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Aura</th><th>Sémiologie typique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Visuelle bilatérale</strong></span> (<span class=\"kw-chiffre\">99 %</span>)</td>\n            <td>\n              <strong>Positifs :</strong> scotome scintillant, phosphènes, zigzags ;<br>\n              <strong>Négatifs / déficitaires :</strong> HLH, amaurose, vision floue (<span class=\"kw-imagerie\">verre dépoli</span>)<br>\n              <em>Aura persiste les yeux fermés et binoculaire (PDF)</em>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Sensitive</strong></span> (<span class=\"kw-chiffre\">30 %</span>)</td>\n            <td>\n              <strong>Marche migraineuse</strong> : <span class=\"kw-clinique\">paresthésies</span> débutant aux <span class=\"kw-clinique\">bouts des doigts</span> → coude → hémiface ;<br>\n              ± hypoesthésie (signes négatifs)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Aphasique</strong></span> (<span class=\"kw-chiffre\">20 %</span>)</td>\n            <td>Manque du mot, <span class=\"kw-clinique\">dysarthrie</span>, <span class=\"kw-clinique\">aphasie</span> totale possible — souvent successive d'une aura visuelle</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Aura atypique</strong></span> (examens obligatoires)</td>\n            <td>\n              <strong>Tronc cérébral / basilaire</strong> (<span class=\"kw-chiffre\">10 %</span>) : <span class=\"kw-clinique\">vertige</span>, ataxie, diplopie, <span class=\"kw-clinique\">dysarthrie</span> ;<br>\n              <strong>Motrice</strong> (<span class=\"kw-chiffre\">6 %</span>) : migraine <span class=\"kw-clinique\">hémiplégique</span> = canalopathie ;<br>\n              <strong>Rétinienne</strong> : visuelle <span class=\"kw-clinique\">MONOCULAIRE</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Diagnostic différentiel</span> de l'aura</th><th>Signe distinctif</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\"><strong>AIT</strong></span></td><td>Déficit <span class=\"kw-clinique\">brutal, d'emblée maximal</span>, durée typiquement <span class=\"kw-chiffre\">&lt; 30 min</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Crise d'épilepsie focale</strong></span></td><td>Durée <span class=\"kw-chiffre\">quelques secondes à minutes</span> (bien plus brève qu'une aura)</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Aura symptomatique</strong></span></td><td><span class=\"kw-etio\">MAV</span>, <span class=\"kw-etio\">microangiopathie cérébrale (CADASIL)</span>, <span class=\"kw-etio\">état hypercoagulable</span> → bilan <span class=\"kw-imagerie\">IRM</span> + <span class=\"kw-ttt\">biologique</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Particularité enfant</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Durée</strong></td><td><span class=\"kw-chiffre\">2 à 4 h</span> (limite inférieure abaissée à <span class=\"kw-chiffre\">2 h</span> <span class=\"kw-bio\">vs</span><span class=\"kw-chiffre\"> 4 h</span> adulte — ICHD-3 Bêta)</td></tr>\n          <tr><td><strong>Topographie</strong></td><td>Plus souvent <span class=\"kw-clinique\">frontale</span> et <span class=\"kw-clinique\">bilatérale</span> qu'unilatérale</td></tr>\n          <tr><td><strong>Signes associés</strong></td><td><span class=\"kw-clinique\">Pâleur</span> ++, troubles digestifs marqués ; calmée par le <span class=\"kw-clinique\">sommeil</span></td></tr>\n          <tr><td><strong>Syndromes périodiques</strong></td><td><span class=\"kw-clinique\">Torticolis</span> paroxystique bénin · <span class=\"kw-clinique\">vertige</span> paroxystique bénin · <span class=\"kw-clinique\">vomissements</span> cycliques · <span class=\"kw-clinique\">migraine abdominale</span> (épisodes paroxystiques NON céphalalgiques)</td></tr>\n          <tr><td><strong>Aura atypique</strong></td><td>Aura du tronc cérébral souvent à l'adolescence (1ʳᵉˢ règles) ; aura motrice = canalopathie</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Allodynie cutanée.</strong> En cas de crises prolongées ou fréquentes, la <span class=\"kw-clinique\">sensibilisation centrale</span> entraîne une allodynie cutanée (douleur en réponse à un stimulus non douloureux : peigne, lunettes). C'est un signe d'aggravation et un FR de chronicisation.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalée</span> · 340 — <span class=\"kw-def\">AVC</span> · 36 — Contraception · 92 — <span class=\"kw-clinique\">Déficit moteur</span>-sensitif membres</em></p>","frequence":4},{"id":"99-5","rang":"A","rubrique":"Diagnostic positif","titre":"Conduire l'interrogatoire et réunir les arguments du diagnostic d'algie vasculaire de la face","contenu":"<p>L'<span class=\"kw-def\">algie vasculaire de la face (AVF)</span> est le chef de file des <span class=\"kw-def\">céphalées trigémino-autonomiques (CTA)</span>. Elle associe une <span class=\"kw-def\">douleur unilatérale stricte</span> très sévère et des <span class=\"kw-def\">signes dysautonomiques homolatéraux</span>, sous-tendus par un <span class=\"kw-def\">générateur hypothalamique</span> avec altération des rythmes circadiens.</p>\n      <table >\n        <thead><tr><th>Critère ICHD-3 — AVF</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A.</strong></td><td><span class=\"kw-chiffre\">≥ 5 crises</span> répondant aux critères B et D</td></tr>\n          <tr>\n            <td><strong>B. Douleur</strong></td>\n            <td>\n              <strong>Intensité :</strong> sévère à très sévère ;<br>\n              <strong>Latéralité :</strong> <span class=\"kw-clinique\">unilatérale stricte</span> (toujours du même côté) ;<br>\n              <strong>Topographie :</strong> orbitaire, sus-orbitaire et/ou temporale (point de départ péri-orbitaire) ;<br>\n              <strong>Durée :</strong> acmé en <span class=\"kw-chiffre\">10-15 min</span> ; durée <span class=\"kw-chiffre\">15 à 180 min</span> (&lt;<span class=\"kw-chiffre\"> 3 h</span>) ; <span class=\"kw-clinique\">cède brusquement</span> ;<br>\n              <strong>Caractère :</strong> broiement / arrachement\n            </td>\n          </tr>\n          <tr>\n            <td><strong>C. <span class=\"kw-chiffre\">≥ 1</span>/2 éléments</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Agitation</span> ou impression d'<span class=\"kw-clinique\">impatience</span> motrice<br>\n              <strong>OU</strong> <span class=\"kw-chiffre\">≥ 1</span> signe/symptôme <span class=\"kw-clinique\">homolatéral</span> à la douleur :<br>\n              · Injection conjonctivale et/ou larmoiement<br>\n              · Congestion / obstruction nasale et/ou rhinorrhée<br>\n              · <span class=\"kw-clinique\">Œdème</span> palpébral<br>\n              · Sudation du front et de la face<br>\n              · Myosis et/ou ptosis (au maximum <span class=\"kw-clinique\">Claude Bernard-Horner incomplet</span> = myosis + ptosis + énophtalmie)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>D. Fréquence</strong></td>\n            <td><span class=\"kw-chiffre\">0,5 à 8 crises/jour</span> en période active (0,5 = 1 tous les <span class=\"kw-chiffre\">2 jours</span>)</td>\n          </tr>\n          <tr><td><strong>E.</strong></td><td>Pas mieux expliqué par autre diagnostic ICHD-3</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Forme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Épisodique (90 %)</strong></span></td>\n            <td>\n              Crises survenant en <strong>périodes</strong> de quelques semaines à mois ;<br>\n              Typiquement <span class=\"kw-chiffre\">2-3/jour</span> à <strong>horaires fixes</strong>, sur <span class=\"kw-chiffre\">2-8 semaines</span> ;<br>\n              Rémissions parfois très longues (<span class=\"kw-chiffre\">&gt; 1 mois</span>) ;<br>\n              <strong>Cycles circadiens</strong> (certains moments de la journée) et <strong>circannuels</strong> (certaines saisons) ;<br>\n              Souvent lié à la <span class=\"kw-etio\">prise d'alcool</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Chronique (10 %)</strong></span></td>\n            <td>\n              Crises au long cours <strong>sans rémission &gt;<span class=\"kw-chiffre\"> 3 mois</span></strong> ;<br>\n              <span class=\"kw-alerte\">Comorbidité psychiatrique importante</span> :<br>\n              · <span class=\"kw-def\">Dépression</span> <span class=\"kw-chiffre\">55 %</span><br>\n              · Agoraphobie <span class=\"kw-chiffre\">30 %</span><br>\n              · Tendance suicidaire <span class=\"kw-chiffre\">25 %</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Diagnostic & Démarche</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Examen clinique</strong></td><td>Normal, hormis les <span class=\"kw-clinique\">signes dysautonomiques/végétatifs</span> homolatéraux</td></tr>\n          <tr><td><strong>Signes associés migraineux</strong></td><td>Souvent présents : <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vomissements</span>, photophobie, phonophobie</td></tr>\n          <tr><td><strong>Comportement</strong></td><td>Agitation motrice ++, irritabilité durant la crise — contraste avec la migraine où le patient s'immobilise dans l'obscurité</td></tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>Paraclinique systématique</strong></span> (selon CEN)</td>\n            <td>\n              <strong>Indication :</strong> systématique pour éliminer une cause secondaire ;<br>\n              <strong>Examens :</strong> <span class=\"kw-imagerie\">IRM cérébrale</span> + <span class=\"kw-imagerie\">angio-IRM ou angio-TDM des TSA</span> ;<br>\n              <strong>Cibles à éliminer :</strong> <span class=\"kw-alerte\">lésion hypothalamo-hypophysaire</span>, <span class=\"kw-alerte\">dissection carotidienne</span> ;<br>\n              <strong>Résultat AVF essentielle :</strong> imagerie normale<br>\n              <em>(non systématique selon collèges ORL/CMF, mais systématique selon le CEN)</em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À distinguer de la migraine.</strong> AVF = douleur <span class=\"kw-clinique\">unilatérale STRICTE</span>, péri-orbitaire, &lt;<span class=\"kw-chiffre\"> 3 h</span>, en salves quotidiennes ; le patient est <span class=\"kw-clinique\">agité</span> (<span class=\"kw-bio\">vs</span> immobile en migraine), signes <span class=\"kw-clinique\">dysautonomiques homolatéraux</span> (<span class=\"kw-bio\">vs</span> migraine où ils sont modestes), sex-ratio <span class=\"kw-chiffre\">5H/1F</span> (<span class=\"kw-bio\">vs</span> 3F/1H).</div>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-imagerie\">IRM</span> systématique au 1ᵉʳ épisode.</strong> Toute AVF inaugurale doit faire éliminer une <span class=\"kw-alerte\">lésion hypothalamo-hypophysaire</span> ou une <span class=\"kw-alerte\">dissection de la carotide homolatérale</span> par IRMc + ARM des TSA — c'est le message clé de l'item.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalée</span></em></p>","frequence":4},{"id":"99-6","rang":"A","rubrique":"Diagnostic positif","titre":"Conduire l'interrogatoire et réunir les arguments du diagnostic de névralgie du trijumeau","contenu":"<p>La <span class=\"kw-def\">névralgie essentielle du trijumeau</span> est due à un <span class=\"kw-def\">conflit vasculo-nerveux</span> à l'angle pontocérébelleux entre la racine du V et une <span class=\"kw-etio\">artère cérébelleuse</span>. La <span class=\"kw-def\">neuropathie trigéminale douloureuse</span> est à distinguer (douleur continue, examen anormal — voir plus bas).</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Critère diagnostique</span> — 8 éléments de Sjaastad</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>1. <strong><span class=\"kw-def\">Terrain</span></strong></td><td><span class=\"kw-clinique\">Femme</span></td></tr>\n          <tr><td>2. <strong>Âge</strong></td><td><span class=\"kw-chiffre\">60 ans</span> (apparition à partir de <span class=\"kw-chiffre\">50-60 ans</span>)</td></tr>\n          <tr><td>3. <strong>Latéralité</strong></td><td>Douleur <span class=\"kw-clinique\">unilatérale</span></td></tr>\n          <tr><td>4. <strong>Territoire</strong></td><td>Territoire de <span class=\"kw-clinique\">V2</span> (le plus fréquent : <span class=\"kw-chiffre\">40 %</span>) — V1 <span class=\"kw-chiffre\">10 %</span>, V3 <span class=\"kw-chiffre\">20 %</span>, ou 2 branches</td></tr>\n          <tr><td>5. <strong>Type</strong></td><td>Douleur <span class=\"kw-clinique\">paroxystique</span></td></tr>\n          <tr><td>6. <strong>Intercrise</strong></td><td><span class=\"kw-clinique\">Sans douleur</span> entre les crises</td></tr>\n          <tr><td>7. <strong>Déclenchement</strong></td><td>Existence d'une <span class=\"kw-clinique\">zone gâchette</span></td></tr>\n          <tr><td>8. <strong>Examen</strong></td><td><span class=\"kw-clinique\">Examen clinique normal</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Sémiologie douleur</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Intensité / Type</strong></td><td>Très intense, fulgurante, en <span class=\"kw-clinique\">éclair</span> ou <span class=\"kw-clinique\">décharge électrique</span></td></tr>\n          <tr><td><strong>Durée crise</strong></td><td>Salves très brèves <span class=\"kw-chiffre\">≤ 2 min</span>, suivies de période réfractaire (<span class=\"kw-chiffre\">1-2 min</span>)</td></tr>\n          <tr><td><strong>Fréquence</strong></td><td><span class=\"kw-chiffre\">5 à 10 salves/jour</span>, formes subintrantes possibles</td></tr>\n          <tr><td><strong>Comportement</strong></td><td><span class=\"kw-clinique\">Patient s'immobilise brièvement</span> dans une attitude douloureuse</td></tr>\n          <tr>\n            <td><strong>Zone gâchette</strong></td>\n            <td>\n              <strong>Cutanée :</strong> pli nasogénien, pourtour bouche, houppe du menton ;<br>\n              <strong>Muqueuse :</strong> brossage des dents, parole, alimentation ;<br>\n              <strong>Gestes déclenchants :</strong> parole, mimique, rire, mastication — le malade tente de garder un visage immobile et mange peu\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\">Drapeau rouge</span> ⚠️</th><th>Suspicion</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Âge de survenue <strong>jeune</strong></span></td><td><span class=\"kw-etio\">SEP</span> (1ʳᵉ étiologie des névralgies trigéminales secondaires)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Douleurs moins intenses</span></td><td><span class=\"kw-etio\">Neuropathie trigéminale douloureuse</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Territoire <strong>V1</strong> prédominant</span></td><td><span class=\"kw-etio\">Zona</span> du ganglion trigéminal</td></tr>\n          <tr><td><span class=\"kw-alerte\">Fond douloureux + paresthésies / hypoesthésie permanente</span></td><td><span class=\"kw-etio\">Neuropathie trigéminale douloureuse</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Accès non paroxystiques</span></td><td>Examens complémentaires</td></tr>\n          <tr><td><span class=\"kw-alerte\">Douleur sur les 3 territoires</span></td><td>Cause symptomatique</td></tr>\n          <tr><td><span class=\"kw-alerte\">Anomalie de l'examen neurologique</span></td><td>Cause symptomatique</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Site anatomique</th><th>Étiologies symptomatiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Intra-axiale</strong><br>(tronc cérébral)</td>\n            <td>\n              <span class=\"kw-etio\">Sclérose en plaques</span> (1ʳᵉ étiologie des névralgies trigéminales secondaires, <span class=\"kw-clinique\">sujet jeune</span> ++) ;<br>\n              <span class=\"kw-etio\">Infarctus latéro-bulbaire</span> ;<br>\n              <span class=\"kw-etio\">Syringobulbie</span> ;<br>\n              <span class=\"kw-etio\">Tumeur intra-axiale</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Angle pontocérébelleux</strong></td>\n            <td>\n              <span class=\"kw-etio\">Neurinome du VIII</span> ;<br>\n              <span class=\"kw-etio\">Méningiome</span>, <span class=\"kw-etio\">cholestéatome</span> et autres tumeurs ;<br>\n              <span class=\"kw-etio\">Anévrisme de l'artère basilaire</span> ;<br>\n              <span class=\"kw-etio\">Zona</span> du ganglion trigéminal\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Base du crâne</strong></td>\n            <td>\n              <span class=\"kw-etio\">Tumeur locale</span> (extension cancer du cavum, méningiome sinus caverneux) ;<br>\n              <span class=\"kw-etio\">Méningite carcinomateuse ou infectieuse</span> ;<br>\n              <span class=\"kw-etio\">Fractures</span> base du crâne, sinus, massif facial ;<br>\n              <span class=\"kw-etio\">Thrombose veineuse</span> du sinus caverneux ;<br>\n              <span class=\"kw-etio\">Microangiopathie du V</span> (<span class=\"kw-def\">diabète</span>, Gougerot-Sjögren, sclérodermie) ;<br>\n              <span class=\"kw-etio\">Dissection carotide interne</span> = <strong><span class=\"kw-clinique\">syndrome de Reader</span></strong> (V1 + Claude Bernard-Horner)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/99/etiologies-nevralgie-v-symptomatique.png\" alt=\"Schéma des étiologies des névralgies et neuropathies trigéminales symptomatiques par site anatomique : tronc cérébral (intra-axiale), angle pontocérébelleux, base du crâne\" loading=\"lazy\">\n        <figcaption>Étiologies des névralgies/neuropathies trigéminales symptomatiques classées par site anatomique : intra-axiale (SEP, <span class=\"kw-clinique\">infarctus</span> latéro-bulbaire, syringobulbie, tumeur intra-axiale), angle pontocérébelleux (neurinome VIII, méningiome, cholestéatome, anévrisme basilaire, zona du ganglion trigéminal), base du crâne (tumeur locale, <span class=\"kw-def\">méningite</span>, fracture, TVC sinus caverneux, microangiopathie du V, <span class=\"kw-etio\">dissection</span> carotidienne = syndrome de Reader). Source : fiche source EDN item 99 — Névralgies faciales et crâniennes.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/99/irm-trijumeau-axiale.png\" alt=\"IRM cérébrale axiale du trijumeau — visualisation de la racine du V à l'angle pontocérébelleux pour la recherche d'un conflit vasculo-nerveux\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">IRM</span> cérébrale axiale, coupes fines sur le trajet du V à l'angle pontocérébelleux : l'examen recherche un conflit vasculo-nerveux entre la racine du nerf trijumeau et une artère cérébelleuse, critère décisionnel pour orienter vers une décompression vasculaire microchirurgicale (cf. obj-14). Source : fiche source EDN item 99 — Névralgies faciales et crâniennes.</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Neuropathie trigéminale douloureuse (à distinguer)</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Douleur</strong></td><td><span class=\"kw-clinique\">Continue</span>, brûlure / serrement / picotements ; paroxysmes brefs possibles mais <span class=\"kw-clinique\">non dominants</span></td></tr>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Hypoesthésie ou dysesthésie</span> (thermique et mécanique) dans 1 ou plusieurs territoires V ;<br>\n              <span class=\"kw-clinique\">Allodynie mécanique</span> et <span class=\"kw-clinique\">hyperalgésie au froid</span> ;<br>\n              Zones allodyniques <span class=\"kw-clinique\">étendues</span> (≠ zone gâchette restreinte de la névralgie) ;<br>\n              Recherche d'<span class=\"kw-clinique\">éruption</span> évocatrice de <span class=\"kw-etio\">zona</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Traitement spécifique</strong></td>\n            <td>Douleur neuropathique focale : <span class=\"kw-ttt\">lidocaïne</span> en emplâtres, TENS, <span class=\"kw-ttt\">duloxétine</span>/<span class=\"kw-ttt\">venlafaxine</span>, <span class=\"kw-ttt\">gabapentine</span>, <span class=\"kw-ttt\">amitriptyline</span> (cf. obj-14)</td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th><span class=\"kw-imagerie\">Paraclinique systématique</span></th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Indication</strong></td><td>Systématique pour éliminer une cause secondaire (non systématique selon ORL)</td></tr>\n          <tr><td><strong>Bilan <span class=\"kw-ttt\">biologique</span></strong></td><td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span></td></tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>IRM cérébrale injectée</strong></span></td>\n            <td>Coupes fines sur le trajet du nerf (tronc cérébral et trijumeau sur tout son trajet) — recherche du conflit vasculo-nerveux et des étiologies secondaires</td>\n          </tr>\n          <tr><td><strong><span class=\"kw-bio\">Ponction lombaire</span></strong></td><td>Non systématique</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Névralgie du glossopharyngien (IX) — à distinguer</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td>Exceptionnelle (<span class=\"kw-chiffre\">1 cas pour 70-100 névralgies du V</span>)</td></tr>\n          <tr><td><strong>Type de douleur</strong></td><td>Comparable à la névralgie du V : <span class=\"kw-clinique\">éclair / décharge électrique</span>, salves <span class=\"kw-chiffre\">≤ 2 min</span>, <span class=\"kw-chiffre\">5-10/jour</span> ; patient s'immobilise brièvement</td></tr>\n          <tr><td><strong>Topographie</strong></td><td>Territoire sensitif du <span class=\"kw-clinique\">IX</span> : <span class=\"kw-clinique\">base de la langue</span>, <span class=\"kw-clinique\">fond de la gorge</span>, <span class=\"kw-clinique\">amygdale</span>, CAE ; <span class=\"kw-clinique\">irradiation</span> vers l'<span class=\"kw-clinique\">angle mandibulaire</span></td></tr>\n          <tr><td><strong>Déclencheurs</strong></td><td><span class=\"kw-clinique\">Parole</span>, <span class=\"kw-clinique\">déglutition</span>, mouvements du cou</td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>Paraclinique</strong></span></td><td><span class=\"kw-imagerie\">IRM</span> avec séquences haute résolution → recherche d'un conflit vasculo-nerveux</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>DD à toujours éliminer</strong></span></td><td><span class=\"kw-alerte\">Carcinome de la base de la langue ou de la tonsille</span> → examen ORL systématique</td></tr>\n          <tr><td><strong>Traitement</strong></td><td>Identique à la névralgie essentielle du V (<span class=\"kw-ttt\">carbamazépine</span>) ; décompression vasculaire si rebelle</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 104 — SEP · 96 — Neuropathie périphérique</em></p>","frequence":5,"liens":[{"href":"https://radiopaedia.org/articles/trigeminal-neuralgia","label":"Radiopaedia : Trigeminal neuralgia"},{"href":"https://radiopaedia.org/articles/trigeminal-nerve","label":"Radiopaedia : Trigeminal nerve (anatomie)"}]},{"id":"99-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l'intrication migraines, céphalées de tension","contenu":"<p>La <span class=\"kw-def\">céphalée de tension</span> et la migraine sont fréquemment intriquées : association concomitante, <span class=\"kw-clinique\">évolution</span> de l'une vers l'autre, ou aboutissement à la <span class=\"kw-def\">céphalée chronique quotidienne (CCQ)</span> ± <span class=\"kw-def\">céphalée par abus médicamenteux (CAM)</span>. <strong>Règle d'or :</strong> toute <span class=\"kw-clinique\">céphalée</span> chronique quotidienne &gt;<span class=\"kw-chiffre\"> 3 mois</span> est une migraine chronique jusqu'à preuve du contraire.</p>\n      <table >\n        <thead><tr><th>Céphalée de tension</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Prévalence</span></strong></td><td><span class=\"kw-chiffre\">30 à 80 %</span> — <span class=\"kw-clinique\">céphalée</span> primaire la plus fréquente ; <span class=\"kw-chiffre\">3F/2H</span>, début à l'adolescence</td></tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Physiopathologie</span></strong></td>\n            <td>\n              Douleurs dysfonctionnelles :<br>\n              · Facteurs périphériques myogènes (<span class=\"kw-clinique\">crispation muscles péri-crâniens</span>) ;<br>\n              · Facteurs neurologiques centraux (dysfonction du contrôle de la douleur)\n            </td>\n          </tr>\n          <tr><td><strong>Latéralité</strong></td><td><span class=\"kw-clinique\">Bilatérale</span> (barre frontale ou cervicale)</td></tr>\n          <tr><td><strong>Intensité</strong></td><td>Légère à modérée</td></tr>\n          <tr><td><strong>Durée</strong></td><td><span class=\"kw-chiffre\">30 min à 7 j</span></td></tr>\n          <tr><td><strong>Type</strong></td><td>Serrement / étau / pression / brûlure / fourmillement</td></tr>\n          <tr><td><strong>Améliorée par</strong></td><td>Activité ou repos</td></tr>\n          <tr><td><strong>Aggravée par</strong></td><td><span class=\"kw-alerte\">Surconsommation d'antalgiques</span></td></tr>\n          <tr><td><strong>Examen</strong></td><td>Sensibilité et crispation à la pression des muscles faciaux ou cervicaux, ou examen normal</td></tr>\n          <tr><td><strong>Signes d'accompagnement</strong></td><td><span class=\"kw-clinique\">Aucun</span> (≠ migraine)</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Céphalée</span> chronique quotidienne (CCQ)</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-chiffre\">≥ 15 j/mois depuis &gt; 3 mois</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Prévalence</span></strong></td><td><span class=\"kw-chiffre\">3 %</span>, prédominance féminine <span class=\"kw-chiffre\">40-50 ans</span></td></tr>\n          <tr>\n            <td><strong>Complication de</strong></td>\n            <td>\n              <span class=\"kw-etio\">Migraine sans aura</span> (&gt; 8 j/mois de <span class=\"kw-clinique\">céphalées</span> migraineuses) <strong>ET/OU</strong><br>\n              <span class=\"kw-etio\">Céphalées de tension épisodiques</span> ;<br>\n              ± <span class=\"kw-alerte\">abus médicamenteux dans 80 % des cas</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>FR</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Fréquence élevée des céphalées</span> (agenda) ;<br>\n              <span class=\"kw-def\">Dépression</span> (échelle HAD) ;<br>\n              <span class=\"kw-alerte\">Surconsommation traitement de crise</span> (limiter <span class=\"kw-chiffre\">≤ 8</span> j/mois)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Sous-types</strong></td>\n            <td>\n              <strong>CCQ courte durée</strong> (crises &lt;<span class=\"kw-chiffre\"> 4 h</span>) : <span class=\"kw-etio\">AVF</span>, <span class=\"kw-etio\">névralgie essentielle du V</span> ;<br>\n              <strong>CCQ longue durée</strong> (crises &gt;<span class=\"kw-chiffre\"> 4 h</span>) : <span class=\"kw-etio\">migraine chronique</span>, <span class=\"kw-etio\">CCQ de novo</span>\n            </td>\n          </tr>\n          <tr><td><strong><span class=\"kw-def\">Comorbidités</span></strong></td><td>Psychiatriques (anxiété/<span class=\"kw-def\">dépression</span>) — baisse de l'efficacité des systèmes de contrôle de la douleur</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Critère ICHD-3 — <span class=\"kw-clinique\">Céphalée</span> par abus <span class=\"kw-etio\">médicamenteux</span> (CAM)</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A.</strong></td><td><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-chiffre\">≥ 15 j/mois</span> chez un patient avec céphalée préexistante</td></tr>\n          <tr>\n            <td><strong>B. Surconsommation &gt;<span class=\"kw-chiffre\"> 3 mois</span></strong></td>\n            <td>\n              <strong><span class=\"kw-ttt\">Antalgiques</span> non-opiacés</strong> (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">aspirine</span>, <span class=\"kw-ttt\">paracétamol</span>) : <span class=\"kw-chiffre\">≥ 15 j/mois</span> ;<br>\n              <strong>Triptans, ergotamine, <span class=\"kw-ttt\">opiacés</span>, antalgiques combinés</strong> : <span class=\"kw-chiffre\">≥ 10 j/mois</span>\n            </td>\n          </tr>\n          <tr><td><strong>C.</strong></td><td>Pas mieux expliqué par autre diagnostic ICHD-3</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Risque le plus élevé.</strong> Les <span class=\"kw-ttt\">opiacés</span> et les <span class=\"kw-ttt\">antalgiques combinés à la caféine</span> exposent au plus haut risque de CAM <strong>et</strong> d'addiction → <span class=\"kw-ci\">interdits dans la céphalée primaire</span> (cf. obj-12 et obj-14).</div>\n      <div class=\"callout callout-info\"><strong>Nuance importante.</strong> Ne pas surestimer le rôle de la surconsommation pour éviter la stigmatisation : la migraine chronique peut être diagnostiquée même avec CAM associée. La surconsommation peut être autant cause que conséquence de l'augmentation de fréquence.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalée</span></em></p>","frequence":0},{"id":"99-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales causes de douleur de la face","contenu":"<p>La <span class=\"kw-def\">douleur de la face</span> est définie comme une douleur située <strong>sous le plan orbito-méatale</strong>, en avant du pavillon de l'oreille et au-dessus du cou. <strong>Cause principale :</strong> origine <span class=\"kw-etio\">dentaire</span>. La douleur est <span class=\"kw-def\">chronique si &gt; 3 mois</span> malgré suppression de la cause ou sans cause retrouvée.</p>\n      <table >\n        <thead><tr><th>Innervation sensitive de la face</th><th>Territoires</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Nerf trijumeau (V)</strong></td><td>Nerf mixte à prédominance sensitive — 3 branches sensitives (V1/V2/V3)</td></tr>\n          <tr><td><span class=\"kw-clinique\">V1 — Ophtalmique</span></td><td>Paupière supérieure, portion médiale paupière inférieure, cornée, conjonctive sup, front, nez (sauf ailes), méninges, muqueuses nez-front-sphénoïde</td></tr>\n          <tr><td><span class=\"kw-clinique\">V2 — Maxillaire</span></td><td>Lèvre sup, joue, ailes narinaires, paupière inférieure, muqueuses gencives supérieures, palais, voile, rhinopharynx, sinus maxillaire, dents maxillaires</td></tr>\n          <tr><td><span class=\"kw-clinique\">V3 — Mandibulaire</span> (sensitivomoteur)</td><td>Mandibule, menton, lèvre inf, MAE, 2/<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> an</span>térieur langue, plancher buccal, gencives, dents, partie sup de l'oreille</td></tr>\n          <tr><td><span class=\"kw-clinique\">Glossopharyngien IX</span></td><td>1/3 postérieur de la langue</td></tr>\n          <tr><td><span class=\"kw-clinique\">VII bis (nerf de Wrisberg)</span></td><td>Conque + partie externe du CAE = <strong>zone de Ramsay-Hunt</strong></td></tr>\n          <tr><td><span class=\"kw-clinique\">Racines C1/C2 et C2/C3</span></td><td>Partie basse / postéro-inférieure du pavillon, CAE, lobule, angle mandibulaire</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Orientation diagnostique</th><th>Sémiologie clé</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Dents & gencive</strong></span></td><td>1ʳᵉ cause de douleur buccale : <span class=\"kw-clinique\">carie</span>, <span class=\"kw-clinique\">pulpopathie</span>, granulomes/kystes apicaux, <span class=\"kw-clinique\">parodontopathie</span></td></tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Muqueuse</strong></span></td>\n            <td>\n              <strong>Tumeur :</strong> <span class=\"kw-alerte\">carcinome épidermoïde</span> = <span class=\"kw-clinique\">ulcération</span> à bords surélevés et indurés, saignant au contact → <span class=\"kw-bio\">biopsie</span> ;<br>\n              <strong>Traumatisme :</strong> prothèse inadaptée, morsure, brûlure ;<br>\n              <strong>Inflammation/immunologique :</strong> aphte, lichen plan, maladies bulleuses (pemphigus, <span class=\"kw-alerte\">Lyell</span>, Stevens-Johnson) ;<br>\n              <strong>Infection :</strong> TB buccale, lymphoréticulose, <span class=\"kw-etio\">CMV</span>, primo-syphilis (indolore), herpès HSV1, VZV, HSV-8, mycose\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Sinus</strong></span></td>\n            <td>\n              <strong>Sinusite aiguë :</strong> douleur sous-orbitaire, irradiante dents/orbite, <span class=\"kw-clinique\">pulsatile</span>, <span class=\"kw-clinique\">aggravée en position proclive</span>, déclenchée par palpation du nerf infra-orbitaire ;<br>\n              <strong>Sinusite chronique :</strong> indolore sauf poussée\n            </td>\n          </tr>\n          <tr><td><span class=\"kw-etio\"><strong>Salive</strong></span></td><td>Lithiase et complications infectieuses locales ; sialadénites virales/bactériennes ; tumeurs des glandes salivaires (indolores si bénignes)</td></tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Os</strong></span></td>\n            <td>\n              <strong>Traumatisme :</strong> fracture mandibulaire ;<br>\n              <strong>Infection :</strong> ostéite (douleur <span class=\"kw-clinique\">lancinante, fluctuante, non rythmée</span>) ;<br>\n              <strong>Ostéonécrose :</strong> radique ou post-bisphosphonates/dénosumab ;<br>\n              <strong>Tumeur :</strong> non douloureuse sauf poussée <span class=\"kw-etio\">inflammatoire</span> ou <span class=\"kw-bio\">envahissement</span> nerveux (<span class=\"kw-clinique\">dysesthésie</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Neurologie</strong></span></td>\n            <td>\n              <span class=\"kw-etio\">Névralgie du V</span> : douleur paroxystique fulgurante, éclair/décharge, zone gâchette (cf. obj-5) ;<br>\n              <span class=\"kw-clinique\">Névralgie d'Arnold</span> (n. grand occipital, C2) : décharge électrique occipitale irradiant vers le <span class=\"kw-clinique\">vertex</span> ± fond douloureux ; déclencheurs = <span class=\"kw-clinique\">mouvements du cou</span>, appui à la base du crâne ; <span class=\"kw-alerte\">piège : sur-diagnostiquée chez les migraineux à prédominance postérieure</span> → ne pas opérer sans avoir éliminé une migraine ;<br>\n              <span class=\"kw-alerte\">Neuropathie du nerf mentonnier</span> (branche terminale V3) : <span class=\"kw-clinique\">dysesthésie/hypoesthésie de la « houppe du menton »</span> → révèle souvent une <span class=\"kw-alerte\">tumeur maligne (LAL, métastase mandibulaire)</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Vasculaire</strong></span></td>\n            <td>\n              <span class=\"kw-etio\">AVF</span> : broiement/brûlure latéralisée fronto-orbitaire pulsatile + vaso-moteur ;<br>\n              <span class=\"kw-alerte\">Maladie de Horton</span> : <span class=\"kw-clinique\">AEG</span>, <span class=\"kw-clinique\">claudication</span> mâchoire, <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-ci\">hypersensibilité</span> cuir chevelu (cf. <span class=\"kw-alerte\">urgence</span> diagnostique) ;<br>\n              <span class=\"kw-etio\">Vascularites à ANCA (Wegener/GPA)</span> : douleur faciale sévère d'horaire <span class=\"kw-clinique\">inflammatoire</span>, atteinte sinusienne ;<br>\n              <span class=\"kw-alerte\">Cancer pulmonaire</span> (invasion ou compression du X) : algie faciale référée via le complexe trigémino-cervical (afférence viscérale du X → noyau solitaire bulbaire)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Oculaire</strong></span></td>\n            <td>\n              <span class=\"kw-alerte\">Glaucome aigu par fermeture de l'angle</span> : douleur localisée à l'œil + <span class=\"kw-clinique\">BAV</span> + <span class=\"kw-clinique\">chémosis</span> ;<br>\n              <span class=\"kw-etio\">Hétérophorie / troubles de la convergence</span> : douleur fronto-glabellaire <span class=\"kw-clinique\">vespérale</span>, déclenchée par le travail sur écran (à distinguer d'une sinusalgie frontale ou d'une <span class=\"kw-clinique\">céphalée</span> de tension)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Articulation temporo-mandibulaire</strong></span></td>\n            <td>\n              <strong>Fracture ATM :</strong> limitation douloureuse pterygoïdiens ;<br>\n              <strong>Luxation bilatérale :</strong> bouche ouverte impossible à fermer → <span class=\"kw-ttt\">réduction</span> par <span class=\"kw-clinique\">manœuvre de Nélaton</span> ;<br>\n              <strong>Dysfonction ATM :</strong> origine musculaire/articulaire, algie dysfonctionnelle\n            </td>\n          </tr>\n          <tr><td><span class=\"kw-etio\"><strong>Idiopathique</strong></span></td><td>Glossodynie, stomatodynie, odontalgies atypiques — <span class=\"kw-clinique\">femme jeune</span>, type brûlure ou picotement</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Pièges à ne pas manquer.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Toute ulcération muqueuse &gt; 2 semaines</span> = <span class=\"kw-bio\">biopsie</span> pour éliminer un cancer (<span class=\"kw-clinique\">carcinome</span> épidermoïde de la cavité buccale)</li>\n          <li><span class=\"kw-alerte\">Maladie de Horton</span> : <span class=\"kw-clinique\">AEG</span> + <span class=\"kw-clinique\">céphalées</span> + <span class=\"kw-clinique\">claudication</span> mâchoire chez le sujet &gt;<span class=\"kw-chiffre\"> 50 ans</span></li>\n          <li><span class=\"kw-alerte\">Dissection carotidienne</span> : algie faciale unilatérale + Claude Bernard-Horner (<span class=\"kw-clinique\">syndrome de Reader</span>)</li>\n          <li><span class=\"kw-alerte\">Cancer ORL avec invasion nerveuse</span> : douleur faciale avec <span class=\"kw-clinique\">dysesthésie</span> (souvent à distance de la tumeur primitive)</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 148 — Infection naso-sinusiennes · 150 — Otite · 349 — Infection aiguë des parties molles : dentaire</em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/occipital-neuralgia","label":"Radiopaedia : Occipital neuralgia (Arnold)"},{"href":"https://radiopaedia.org/articles/temporomandibular-joint-1","label":"Radiopaedia : Temporomandibular joint"}]},{"id":"99-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la description clinique des algies d'origine dentaire, sinusienne et buccale","contenu":"<p>Les <span class=\"kw-def\">algies d'origine dentaire</span> sont la <strong>1ʳᵉ cause</strong> des douleurs faciales. Les algies <span class=\"kw-def\">sinusiennes</span> (sinusites aiguës/chroniques) et <span class=\"kw-def\">buccales</span> (muqueuses, os de la face) complètent le tableau. <strong>Règle absolue :</strong> toute <span class=\"kw-clinique\">ulcération</span> muqueuse &gt;<span class=\"kw-chiffre\"> 2 semaines</span> = <span class=\"kw-bio\">biopsie</span>.</p>\n      <table >\n        <thead><tr><th>Algie dentaire</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Carie</strong></span></td><td>1ʳᵉ cause de douleur buccale ; douleur déclenchée par stimulus thermique (froid/chaud) ou alimentaire</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Pulpopathie</strong></span></td><td>Inflammation pulpe dentaire ; douleur intense, spontanée, irradiante, exacerbée par décubitus (rage de dents)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Granulomes / kystes apicaux</strong></span></td><td>Douleur sourde, persistante ; mobilité dentaire ; visible à la <span class=\"kw-imagerie\">panoramique dentaire</span></td></tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Parodontite aiguë</strong></span></td>\n            <td>\n              Inflammation des tissus de soutien ;<br>\n              <strong>Type :</strong> <span class=\"kw-clinique\">pulsatile, lancinante</span> ;<br>\n              <strong><span class=\"kw-clinique\">Irradiation</span> :</strong> <span class=\"kw-clinique\">trijéminale</span> ;<br>\n              <strong>Majorée par :</strong> <span class=\"kw-clinique\">décubitus</span>, <span class=\"kw-clinique\">percussion axiale</span> ;<br>\n              <strong>Signe :</strong> sensation de <span class=\"kw-clinique\">dent longue au serrage</span> ;<br>\n              Saignement gingival, mobilité dentaire\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Algie sinusienne</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Sinusite aiguë</strong></span></td>\n            <td>\n              Douleur <span class=\"kw-clinique\">sous-orbitaire</span>, irradiant vers dents et orbite ;<br>\n              <span class=\"kw-clinique\">Pulsatile</span>, sensation de <span class=\"kw-clinique\">pesanteur</span>/tension ;<br>\n              <span class=\"kw-clinique\">Aggravée par l'effort</span> et la <span class=\"kw-clinique\">position proclive</span> (tête penchée en avant) ;<br>\n              Déclenchée par <span class=\"kw-clinique\">palpation du nerf infra-orbitaire</span> ;<br>\n              <span class=\"kw-radio\">Comblement</span> à la <span class=\"kw-imagerie\">TDM</span>\n            </td>\n          </tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Sinusite chronique</strong></span></td><td><span class=\"kw-clinique\">Indolore</span> sauf en poussée infectieuse</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Algie buccale (muqueuse)</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Carcinome épidermoïde</strong></span></td>\n            <td>\n              <strong>Aspect :</strong> <span class=\"kw-clinique\">ulcération</span> à <span class=\"kw-clinique\">bords surélevés et indurés</span>, saignant au contact ;<br>\n              Parfois <span class=\"kw-clinique\">non visible</span> si sous-muqueux mais palpable ;<br>\n              Douleurs spontanées + provoquées par <span class=\"kw-clinique\">mastication</span> → limitation alimentaire ;<br>\n              <strong>Examen :</strong> <span class=\"kw-bio\">biopsie</span> indispensable\n            </td>\n          </tr>\n          <tr><td><strong>Traumatisme dentaire</strong></td><td>Prothèse inadaptée, morsure, brûlure ; <span class=\"kw-clinique\">ulcération</span> à <span class=\"kw-clinique\">bords réguliers, discrètement érythémateuse, pas d'induration</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Aphte buccal</strong></span> (C)</td><td><span class=\"kw-clinique\">Ulcération</span> unique arrondie, bords réguliers fibrineux entourés d'un halo ; douleur insomniante, exacerbée par ingestion alimentaire</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Lichen plan</strong></span> (C)</td><td><span class=\"kw-chiffre\">1-2 %</span> de la population, lésions blanchâtres évoluant sur des années ; <span class=\"kw-alerte\">transformation maligne</span> → <span class=\"kw-def\">surveillance</span> régulière</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Maladies bulleuses</strong></span> (C)</td><td>Auto-immunes : pemphigus vulgaire, pemphigoïde bulleuse ; iatrogènes : <span class=\"kw-clinique\">syndrome de Lyell</span>, <span class=\"kw-alerte\">Stevens-Johnson</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Stomatite localisée</strong></span> (C)</td><td>TB buccale (<span class=\"kw-clinique\">ulcération</span> irrégulière non indurée à fond jaunâtre), lymphoréticulose bénigne d'inoculation, <span class=\"kw-etio\">CMV</span>, primo-syphilis (<span class=\"kw-clinique\">indolore</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Stomatite diffuse</strong></span> (C)</td><td>Herpès HSV1, <span class=\"kw-etio\">VZV</span>, HSV-8, <span class=\"kw-etio\">staphylocoque</span>, streptocoque, mycose (douleur à type de <em>cuisson</em>)</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Ostéonécroses mandibulaires</th><th>Sémiologie & CAT</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Ostéoradionécrose</strong></span><br>(post-<span class=\"kw-ttt\">radiothérapie</span> ORL)</td>\n            <td>\n              <strong>Délai :</strong> apparition <span class=\"kw-chiffre\">≥ 3 mois</span> après la fin de l'<span class=\"kw-clinique\">irradiation</span> ; <span class=\"kw-alerte\">risque permanent &gt; 10 ans</span> ;<br>\n              <strong>FR :</strong> dose <span class=\"kw-imagerie\">RT</span>, <span class=\"kw-etio\">tabagisme</span>, hygiène buccodentaire, <span class=\"kw-alerte\">extraction dentaire après irradiation</span> ;<br>\n              <strong>Clinique :</strong> <span class=\"kw-clinique\">douleur intense</span> + <span class=\"kw-clinique\">trismus</span> ; <span class=\"kw-chiffre\">50 %</span> spontanées,<span class=\"kw-chiffre\"> 50 %</span> post-geste ;<br>\n              <strong>RX :</strong> <span class=\"kw-radio\">ostéolyse mal limitée</span>, <span class=\"kw-radio\">fracture pathologique</span>, <span class=\"kw-radio\">séquestre</span> ;<br>\n              <strong>DD :</strong> récidive / poursuite évolutive du cancer (à toujours discuter) ;<br>\n              <strong>Traitement :</strong> <span class=\"kw-ttt\">ATB</span> ± <span class=\"kw-ttt\">oxygénothérapie hyperbare</span> ; <span class=\"kw-ttt\">curetage osseux</span> ou <span class=\"kw-ttt\">mandibulectomie interruptrice</span> si médical insuffisant ;<br>\n              <strong>Prévention :</strong> <span class=\"kw-clinique\">avulsion de toute dent non traitable AVANT irradiation</span> ; à vie = fluoration par gouttière ; avulsions post-RT <span class=\"kw-clinique\">sous ATB</span> + <span class=\"kw-clinique\">fermeture muqueuse étanche</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Ostéochimionécrose</strong></span><br>(bisphosphonates / dénosumab — rang C)</td>\n            <td>\n              <strong>Contexte :</strong> <span class=\"kw-clinique\">retard de cicatrisation après traumatisme muqueux</span> (souvent post-extraction) ;<br>\n              <strong>Clinique :</strong> douleur inconstante, sensation d'engourdissement, lourdeur de la mâchoire ; <span class=\"kw-clinique\">mobilité dentaire</span>, perte de substance muqueuse avec <span class=\"kw-clinique\">exposition osseuse</span> ;<br>\n              <strong>RX :</strong> initialement normale, puis <span class=\"kw-radio\">image ostéolytique mal limitée</span> ± <span class=\"kw-radio\">séquestre osseux</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Règle absolue de cancérologie ORL.</strong> Toute <span class=\"kw-alerte\">ulcération muqueuse persistant &gt; 2 semaines</span> = <span class=\"kw-bio\">biopsie</span> pour éliminer un cancer (<span class=\"kw-clinique\">carcinome</span> épidermoïde de la cavité buccale). Ne jamais attribuer une <span class=\"kw-clinique\">ulcération</span> chronique à un simple traumatisme.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 148 — Infection naso-sinusiennes · 349 — Infection aiguë des parties molles : dentaire · 298 — Tumeur cavité buccale-nasosinusienne-cavum-VADS</em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/impacted-teeth","label":"Radiopaedia : Impacted teeth"},{"href":"https://radiopaedia.org/articles/mandibular-osteoradionecrosis","label":"Radiopaedia : Mandibular osteoradionecrosis"}]},{"id":"99-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la description clinique des céphalées d'origine auriculaire","contenu":"<p>Les <span class=\"kw-def\">céphalées d'origine auriculaire</span> sont des douleurs perçues au niveau de l'oreille ou de la région péri-auriculaire, dont l'origine peut être <strong>primaire</strong> (pathologie auriculaire) ou <strong>réflexe</strong> (douleur projetée par convergence sensitive du V, VII bis, IX, X et C2-C3).</p>\n      <table >\n        <thead><tr><th>Cause auriculaire primaire</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Otite moyenne aiguë (OMA)</strong></span></td>\n            <td>\n              Douleur <span class=\"kw-clinique\">pulsatile</span> de l'oreille, <span class=\"kw-alerte\">fièvre</span>, <span class=\"kw-clinique\">hypoacousie de transmission</span> ;<br>\n              <span class=\"kw-imagerie\">Otoscopie</span> : tympan <span class=\"kw-radio\">bombé, inflammatoire</span>, ± <span class=\"kw-clinique\">perforation</span> ;<br>\n              Contexte : <span class=\"kw-etio\">enfant</span>, infection <span class=\"kw-etio\">rhinopharyngée</span> récente\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Otite externe</strong></span></td>\n            <td>\n              Douleur déclenchée par <span class=\"kw-clinique\">mobilisation du pavillon ou du tragus</span> (signe pathognomonique) ;<br>\n              <span class=\"kw-imagerie\">Otoscopie</span> : CAE <span class=\"kw-clinique\">érythémateux</span>, <span class=\"kw-clinique\">œdémateux</span> ± sténosé ;<br>\n              Contexte : <span class=\"kw-etio\">baignade</span>, <span class=\"kw-etio\">manipulation</span> (coton-tige)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Mastoïdite aiguë</strong></span><br>(complication d'OMA)</td>\n            <td>\n              <span class=\"kw-alerte\">Urgence ORL pédiatrique</span> — souvent suite d'une OMA mal/non traitée ;<br>\n              <span class=\"kw-clinique\">Décollement du pavillon</span> + <span class=\"kw-clinique\">tuméfaction rétro-auriculaire</span> <span class=\"kw-etio\">inflammatoire</span> ;<br>\n              <span class=\"kw-alerte\">Fièvre élevée</span>, <span class=\"kw-clinique\">AEG</span> ;<br>\n              <span class=\"kw-imagerie\">TDM des rochers</span> en <span class=\"kw-alerte\">urgence</span> → <span class=\"kw-radio\">comblement mastoïdien + lyse osseuse</span> ;<br>\n              <span class=\"kw-alerte\">CI à la chirurgie ambulatoire</span> — <span class=\"kw-alerte\">hospitalisation</span>, ATB IV ± mastoïdectomie\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Zona du géniculé</strong></span><br>= <span class=\"kw-clinique\">syndrome de Ramsay</span>-Hunt</td>\n            <td>\n              <span class=\"kw-clinique\">Éruption vésiculeuse</span> dans la <span class=\"kw-clinique\">zone de Ramsay-Hunt</span> (conque + CAE — territoire VIIbis) ;<br>\n              + <span class=\"kw-clinique\">paralysie faciale périphérique homolatérale</span> ;<br>\n              ± <span class=\"kw-clinique\">acouphènes</span>, <span class=\"kw-clinique\">vertiges</span> (atteinte VIII associée) ;<br>\n              <strong>Traitement :</strong> <span class=\"kw-ttt\">aciclovir</span> + <span class=\"kw-ttt\">corticoïdes</span> précoces &lt;<span class=\"kw-chiffre\"> 72 h</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Otalgie</span> réflexe (projetée)</th><th>Origine à rechercher</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Dentaire</strong></span></td><td>V3 — caries, pulpopathies, accident d'<span class=\"kw-clinique\">évolution</span> dent de sagesse</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Sinusienne</strong></span></td><td>V2 — sinusite maxillaire</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Pharynx / larynx</strong></span></td><td>IX et X — angine, cancer pharyngé/laryngé</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>ATM</strong></span></td><td>V3 — dysfonction ATM, arthrose</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Rachis cervical</strong></span></td><td>C2-C3 — cervicarthrose, névralgie d'Arnold</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Règle d'or.</strong> Toute <span class=\"kw-clinique\">otalgie avec otoscopie normale</span> impose la <strong>recherche d'une cause à distance</strong> : dent (V3), sinus (V2), pharynx-larynx (IX-X), ATM (V3), rachis cervical (C2-C3). Chez le fumeur/éthylique, <span class=\"kw-ci\">ne jamais</span> méconnaître un cancer pharyngé/laryngé.</div>\n      <div class=\"callout callout-info\"><strong>Note de build.</strong> Les fiches sources de l'item 99 ne détaillent pas exhaustivement les <span class=\"kw-clinique\">céphalées</span> auriculaires — la couverture est synthétique et renvoie principalement à l'item 150 (Otite) pour le détail des pathologies otologiques primaires.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 150 — Otite</em></p>","frequence":0},{"id":"99-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires de première intention devant une douleur de la face","contenu":"<p>Les <span class=\"kw-def\">examens de 1ʳᵉ intention</span> devant une douleur de la face dépendent du site et de l'étiologie suspectée. <strong>Principe :</strong> imagerie ciblée selon le contexte clinique, biologie pour rechercher infection/inflammation, <span class=\"kw-bio\">biopsie</span> pour toute <span class=\"kw-clinique\">lésion</span> suspecte.</p>\n      <table >\n        <thead><tr><th>Imagerie</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>Panoramique dentaire</strong></span></td>\n            <td>Dents, racines, os adjacents, calculs salivaires, articulations — examen de débrouillage</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>TDM / CBCT (cone beam)</strong></span></td>\n            <td>Os de la face : sinus, dents (apex), ATM, fractures, ostéite — examen de référence pour l'os</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>Échographie ou IRM</strong></span></td>\n            <td>Parties molles : tumeurs, lithiases salivaires, infections profondes</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>IRM cérébrale ± injection</strong></span></td>\n            <td>Suspicion de cause neurologique : névralgie V, AVF (+ <span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">IRM</span></span> TSA), <span class=\"kw-clinique\">céphalée</span> secondaire</td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Biologie</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\"><strong>Prélèvements bactériologiques + virologiques + mycologiques</strong></span></td><td>Suspicion infection muqueuse / sialadénite / stomatite</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Cytoponction</strong></span></td><td><span class=\"kw-clinique\">Adénopathies</span>, <span class=\"kw-clinique\">tuméfaction</span> parotidienne ou cervicale</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Biopsie</strong></span></td><td>Indispensable si <span class=\"kw-clinique\">lésion</span> <span class=\"kw-etio\">tumorale</span> ou <span class=\"kw-alerte\">ulcération &gt; 2 semaines</span> ; ulcérations buccales étendues → conservation dans <span class=\"kw-bio\">liquide de Mitchell</span></td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>NFS, CRP</strong></span></td><td>Recherche infection / inflammation systémique (Horton, <span class=\"kw-def\">méningite</span> carcinomateuse)</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Céphalée</span> — Indication d'imagerie</th><th>Modalité</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Migraine épisodique sans aura, critères ICHD-3 complets, examen normal, &gt;<span class=\"kw-chiffre\"> 1 an</span> d'<span class=\"kw-clinique\">évolution</span></strong></td><td><span class=\"kw-clinique\">Pas d'imagerie</span></td></tr>\n          <tr>\n            <td><strong>Migraine — <span class=\"kw-imagerie\">IRM</span> <span class=\"kw-chiffre\">≥ 1</span> fois indiquée</strong></td>\n            <td>\n              Début &gt;<span class=\"kw-chiffre\"> 50 ans</span> ;<br>\n              Migraine avec aura ;<br>\n              Migraine chronique\n            </td>\n          </tr>\n          <tr><td><strong>AVF, névralgie V essentielle</strong></td><td><span class=\"kw-imagerie\">IRMc ± angio-IRM/TDM des TSA</span> systématique (élimine <span class=\"kw-clinique\">lésion</span> hypothalamo-hypophysaire, <span class=\"kw-etio\">dissection</span> carotidienne, conflit vasculo-nerveux)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Imagerie urgente</strong> nécessaire chez tout patient présentant une <span class=\"kw-clinique\">céphalée</span> avec :\n        <ul>\n          <li><span class=\"kw-alerte\">Début brutal</span> ou en coup de tonnerre</li>\n          <li><span class=\"kw-alerte\">Début récent + aggravation progressive &lt; 7 jours</span></li>\n          <li><span class=\"kw-alerte\">Fièvre</span> associée (sans cause générale évidente)</li>\n          <li><span class=\"kw-alerte\">Signes neurologiques</span> associés</li>\n          <li>Caractéristiques suggérant une <span class=\"kw-alerte\">intoxication au CO</span></li>\n          <li><span class=\"kw-alerte\">Contexte d'immunodépression</span></li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalée</span></em></p>","frequence":0},{"id":"99-12","rang":"A","rubrique":"Étiologies","titre":"Identifier les facteurs favorisants éventuels d'une migraine","contenu":"<p>La migraine est une <span class=\"kw-def\">pathologie neurovasculaire de l'adaptation aux changements</span>. Les <span class=\"kw-def\">facteurs déclenchants</span> sont des perturbateurs de l'homéostasie cérébrale. <strong>Point commun :</strong> changement, intrinsèque ou extrinsèque.</p>\n      <table >\n        <thead><tr><th>Catégorie de FD</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>1. Psychologiques</strong></span></td>\n            <td><span class=\"kw-etio\">Contrariété</span>, <span class=\"kw-etio\">anxiété</span>, <span class=\"kw-etio\">émotions</span> positives ou négatives, mariage</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>2. Hormonaux</strong></span></td>\n            <td><span class=\"kw-etio\">Règles</span> (crises cataméniales), <span class=\"kw-etio\">contraceptifs oraux</span>, traitement hormonal, <span class=\"kw-etio\">post-partum</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>3. Stress / modification du mode de vie</strong></span></td>\n            <td><span class=\"kw-etio\">Déménagement</span>, changement de travail, <span class=\"kw-etio\">surmenage</span>, <span class=\"kw-etio\">décompression</span> (vacances, week-end), voyage</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>4. Sensoriels</strong></span></td>\n            <td><span class=\"kw-etio\">Lumière</span>, <span class=\"kw-etio\">bruit</span>, <span class=\"kw-etio\">odeurs</span>, vibrations</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>5. Aliments</strong></span></td>\n            <td><span class=\"kw-etio\">Alcool</span>, <span class=\"kw-etio\">repas riches</span> (graisses cuites, fromages), <span class=\"kw-etio\">agrumes</span> — <span class=\"kw-ci\">∅ Chocolat (PDF EDN)</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>6. Climatiques</strong></span></td>\n            <td><span class=\"kw-etio\">Vent</span>, <span class=\"kw-etio\">chaleur humide</span> (temps orageux), <span class=\"kw-etio\">froid</span>, changement de <span class=\"kw-etio\">pression atmosphérique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>7. Habitudes alimentaires</strong></span></td>\n            <td><span class=\"kw-etio\">Repas sautés</span> ou irréguliers, <span class=\"kw-etio\">jeûne</span>, <span class=\"kw-etio\">sevrage caféine</span>, hydratation insuffisante</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>8. Autres</strong></span></td>\n            <td><span class=\"kw-etio\">Traumatisme crânien</span> (enfant), <span class=\"kw-etio\">manque ou excès de sommeil</span> (grasse matinée), <span class=\"kw-etio\">altitude</span>, <span class=\"kw-etio\">effort physique inhabituel</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège pédagogique majeur.</strong> Le rôle des facteurs déclenchants est <strong>surestimé</strong> par les patients. La phase de <span class=\"kw-clinique\">prodromes</span> comporte une dysfonction hypothalamique avec <span class=\"kw-clinique\">fringale</span> (chocolat, gâteaux) et <span class=\"kw-clinique\">hypersensibilité sensorielle</span> → le patient attribue à tort la <span class=\"kw-clinique\">céphalée</span> ultérieure à ces aliments ou à une lumière, un bruit, une odeur. Conséquence : <span class=\"kw-ci\">éviter les comportements d'éviction draconiens</span> (régimes restrictifs) qui détériorent la qualité de vie sans bénéfice.</div>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-ttt\">Règles hygiéno-diététiques</span> générales (conseils de bon sens).</strong> Sommeil suffisant aux horaires réguliers ; repas équilibrés et réguliers ; hydratation optimale ; activité physique régulière. Ces règles s'intègrent au traitement de fond non <span class=\"kw-etio\">médicamenteux</span>.</div>","frequence":0},{"id":"99-13","rang":"A","rubrique":"Étiologies","titre":"Connaître l'existence de céphalées induites par les médicaments chez le migraineux","contenu":"<p>La <span class=\"kw-def\">céphalée par abus médicamenteux (CAM)</span> est une cause majeure de chronicisation de la migraine. Elle survient sur un <span class=\"kw-def\">terrain</span> de <span class=\"kw-clinique\">céphalée</span> préexistante (migraine ou tension) avec <strong>surconsommation chronique de traitements de crise</strong> &gt;<span class=\"kw-chiffre\"> 3 mois</span>.</p>\n      <table >\n        <thead><tr><th>Critère ICHD-3 — CAM</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A.</strong></td><td><span class=\"kw-clinique\">Céphalée</span> <span class=\"kw-chiffre\">≥ 15 j/mois</span> chez un patient ayant une céphalée préexistante</td></tr>\n          <tr>\n            <td><strong>B. Surconsommation &gt;<span class=\"kw-chiffre\"> 3 mois</span></strong></td>\n            <td>\n              <span class=\"kw-ttt\"><strong>Antalgiques non-opiacés</strong></span> (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">aspirine</span>, <span class=\"kw-ttt\">paracétamol</span>) : <span class=\"kw-chiffre\">≥ 15 j/mois</span> ;<br>\n              <span class=\"kw-ttt\"><strong>Triptans, ergotamine, opiacés et antalgiques combinés</strong></span> : <span class=\"kw-chiffre\">≥ 10 j/mois</span>\n            </td>\n          </tr>\n          <tr><td><strong>C.</strong></td><td>Pas mieux expliqué par un autre diagnostic de l'ICHD-3</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Risque par classe</th><th>Mécanisme / Conséquence</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\"><strong>Opiacés (palier 2 et 3)</strong></span></td><td><strong>Risque le plus élevé</strong> de CAM <em>et</em> d'addiction → <span class=\"kw-ci\">interdits</span> dans la <span class=\"kw-clinique\">céphalée</span> primaire</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Antalgiques combinés à la caféine</strong></span></td><td>Risque comparable aux <span class=\"kw-ttt\">opiacés</span> — <span class=\"kw-ci\">à éviter</span></td></tr>\n          <tr><td><strong>Triptans, ergotamine</strong></td><td>Risque modéré — limite à <span class=\"kw-chiffre\">≤ 10 j/mois</span></td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">aspirine</span>, <span class=\"kw-ttt\">paracétamol</span></strong></td><td>Risque le plus faible — limite à <span class=\"kw-chiffre\">≤ 15 j/mois</span> ; cible pratique : <span class=\"kw-chiffre\">≤ 8 j/mois</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Prise en charge migraine chronique + CAM</th><th>Stratégie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Traitement de fond 1ʳᵉ ligne</strong></td>\n            <td><span class=\"kw-ttt\">Amitriptyline</span>, <span class=\"kw-ttt\">candésartan</span>, <span class=\"kw-ttt\">métoprolol</span>, <span class=\"kw-ttt\">propranolol</span>, <span class=\"kw-ttt\">topiramate</span></td>\n          </tr>\n          <tr><td><strong><span class=\"kw-ttt\">Sevrage</span></strong></td><td>Conseiller un <span class=\"kw-clinique\">sevrage ambulatoire</span> du médicament surconsommé</td></tr>\n          <tr><td><strong>Traitement de crise alternatif</strong></td><td>Prescrire un autre traitement de crise pour gérer la <span class=\"kw-clinique\">céphalée</span> de rebond et les crises résiduelles ; <strong>cible : 8 j/mois</strong></td></tr>\n          <tr><td><strong>Si <span class=\"kw-ttt\">sevrage</span> bénéfique</strong></td><td>Reprise possible des triptans ± <span class=\"kw-ttt\">AINS</span> de crise</td></tr>\n          <tr><td><strong>Si <span class=\"kw-ttt\">sevrage</span> non bénéfique</strong></td><td>= <span class=\"kw-alerte\">migraine chronique vraie</span> → toxine botulique (∅ AMM, hospitalier)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Interdiction absolue (PDF EDN).</strong> Ne pas prescrire d'<span class=\"kw-ttt\">antalgiques opiacés</span> dans les <span class=\"kw-clinique\">céphalées</span> et les algies faciales primaires, car ils exposent au <span class=\"kw-alerte\">double risque de céphalée par abus médicamenteux et d'addiction</span>.</div>\n      <div class=\"callout callout-info\"><strong>Nuance importante.</strong> Ne pas surestimer le rôle de la surconsommation pour éviter la stigmatisation des patients. La migraine chronique peut être diagnostiquée avec un abus <span class=\"kw-etio\">médicamenteux</span> associé. La surconsommation peut être autant <span class=\"kw-clinique\">conséquence</span> que <span class=\"kw-clinique\">cause</span> de l'augmentation de la fréquence des <span class=\"kw-clinique\">céphalées</span>.</div>","frequence":1},{"id":"99-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes généraux du traitement","contenu":"<p>La prise en charge du migraineux repose sur 2 axes : <span class=\"kw-def\">traitement de la crise</span> (action sur les <span class=\"kw-clinique\">céphalées</span>, ne modifie pas la fréquence ni les auras) et <span class=\"kw-def\">traitement de fond</span> (réduit la fréquence et la sévérité, sans faire disparaître les crises). L'évaluation initiale et le <span class=\"kw-def\">suivi</span> reposent sur l'<span class=\"kw-bio\">agenda des céphalées</span> et le <span class=\"kw-def\">score HIT-6</span>.</p>\n      <table >\n        <thead><tr><th>Évaluation initiale</th><th>Outils</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Retentissement</strong></td><td><span class=\"kw-bio\">HIT-6</span> (Headache Impact Test) + <span class=\"kw-bio\">agenda des céphalées</span></td></tr>\n          <tr>\n            <td><strong>Migraine sévère (définition française)</strong></td>\n            <td>\n              <span class=\"kw-chiffre\">≥ 8 j/mois</span> de migraine <strong>OU</strong><br>\n              <span class=\"kw-chiffre\">HIT-6 ≥ 60</span> <strong>OU</strong><br>\n              <span class=\"kw-clinique\">Céphalées</span> nécessitant l'<span class=\"kw-clinique\">interruption complète des activités</span> dans <span class=\"kw-chiffre\">≥ 50 %</span> des cas\n            </td>\n          </tr>\n          <tr><td><strong>Migraine résistante</strong></td><td><span class=\"kw-clinique\">Échec de ≥ 3 classes</span> de traitement de fond</td></tr>\n          <tr><td><strong>Migraine réfractaire</strong></td><td><span class=\"kw-clinique\">Échec de tous</span> les traitements de fond</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Stratégie globale</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Explications</strong></td>\n            <td>Crises = affection neurologique <span class=\"kw-etio\">héréditaire</span> ; les examens ne « voient » pas la maladie ; pas de guérison définitive mais maladie modulable</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Règles hygiéno-diététiques</span></strong></td>\n            <td><span class=\"kw-clinique\">Sommeil régulier</span>, repas équilibrés, hydratation, activité physique d'endurance (cf. obj-15)</td>\n          </tr>\n          <tr>\n            <td><strong>Prévenir la chronicisation</strong></td>\n            <td>\n              Dépister/lutter contre les FR :<br>\n              · <span class=\"kw-alerte\">Fréquence élevée des céphalées</span> (agenda) → justifie une prophylaxie ;<br>\n              · <span class=\"kw-def\">Dépression</span> (échelle HAD) → à prendre en charge ;<br>\n              · <span class=\"kw-clinique\">Surconsommation</span> de traitement de crise → limiter à <span class=\"kw-chiffre\">≤ 8 j/mois</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Traitement de crise</strong></td>\n            <td>À prendre lors de chaque crise pour obtenir un soulagement dans les <span class=\"kw-chiffre\">2 h</span>, sans récurrence dans les <span class=\"kw-chiffre\">24 h</span> ; <strong>n'agit pas sur la fréquence ni sur les auras</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Traitement de fond</strong></td>\n            <td>Vise à diminuer la fréquence et la sévérité ; <strong>ne fait pas disparaître les crises</strong></td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Indications du traitement de fond</th><th>Critère</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td>Traitement de crise utilisé <span class=\"kw-chiffre\">≥ 8 j/mois depuis &gt; 3 mois</span></td></tr>\n          <tr><td><strong>Sévérité</strong></td><td>Migraine sévère (critères définition française)</td></tr>\n          <tr><td><strong>Forme</strong></td><td>Migraine chronique (critères ICHD-3)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Score</span></strong></td><td><span class=\"kw-chiffre\">HIT-6 ≥ 60</span></td></tr>\n          <tr><td><strong>Crises invalidantes</strong></td><td>Malgré l'optimisation du traitement de crise</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Objectifs du traitement de fond</th><th>Cible</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Migraine épisodique</strong></td><td>Réduire les jours de <span class=\"kw-clinique\">céphalée</span> de <span class=\"kw-chiffre\">-50 %</span></td></tr>\n          <tr><td><strong>Migraine chronique</strong></td><td>Réduire les jours de <span class=\"kw-clinique\">céphalée</span> de <span class=\"kw-chiffre\">-30 %</span></td></tr>\n          <tr><td><strong>Autres</strong></td><td>Réduire la consommation des traitements de crise, l'intensité et la durée des crises</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Visite de <span class=\"kw-def\">suivi</span> à<span class=\"kw-chiffre\"> 2-3 mois</span> — 5 questions clés.</strong>\n        <ol>\n          <li>Capable de reprendre rapidement vos activités (travail, social) après la prise du traitement ?</li>\n          <li>Êtes-vous suffisamment soulagé<span class=\"kw-chiffre\"> 1 à 2 heures</span> après la prise lors de la plupart des crises ?</li>\n          <li>Utilisez-vous une seule prise de ce traitement dans les mêmes <span class=\"kw-chiffre\">24 heures</span> ?</li>\n          <li>Êtes-vous suffisamment confiant dans ce traitement pour planifier vos activités ?</li>\n          <li>Ce traitement est-il bien toléré ?</li>\n        </ol>\n      </div>","frequence":0},{"id":"99-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement de la migraine et connaître les règles de prise d'un médicament","contenu":"<p>Le traitement repose sur 2 axes : <span class=\"kw-def\">crise</span> (<span class=\"kw-ttt\">AINS</span>, triptans, <span class=\"kw-ttt\">métoclopramide</span>) et <span class=\"kw-def\">fond</span> (<span class=\"kw-ttt\">bêtabloquants</span>, topiramate, amitriptyline, candésartan, ± anti-CGRP, ± botox). Les <span class=\"kw-def\">règles de prise</span> sont strictes : prise précoce, limites de fréquence, évaluation à<span class=\"kw-chiffre\"> 3 mois</span>.</p>\n      <table >\n        <thead><tr><th>Traitement de crise — Classe</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Paracétamol</strong></span></td>\n            <td>Auto-médication ; <span class=\"kw-ci\">éviter les associations à la caféine</span> et aux <span class=\"kw-ttt\">opiacés</span> palier 2-3 (risque CAM + addiction)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>AINS</strong></span></td>\n            <td>\n              <strong>AMM :</strong> <span class=\"kw-ttt\">aspirine</span> dose anti-<span class=\"kw-etio\">inflammatoire</span>, <span class=\"kw-ttt\">ibuprofène</span>, <span class=\"kw-ttt\">kétoprofène</span> ;<br>\n              <strong>Pas d'AMM :</strong> <span class=\"kw-ttt\">naproxène</span>, diclofénac, indométacine ;<br>\n              <span class=\"kw-ci\"><strong>CI :</strong></span> UGD évolutif, <span class=\"kw-ci\">grossesse &gt; 24 SA</span>, <span class=\"kw-ci\">allergie</span>/<span class=\"kw-ci\">asthme</span> à l'<span class=\"kw-ttt\">aspirine</span> ;<br>\n              <strong>EI :</strong> troubles digestifs, hémorragies, allergie\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Triptans</strong></span><br>(= traitement le + efficace)</td>\n            <td>\n              <strong>Mécanisme :</strong> agonistes 5-HT1B/1D = vasoconstricteurs ;<br>\n              <span class=\"kw-ci\"><strong>CI absolues (ATCD vasculaires) :</strong></span> coronaropathies, pathologie artérielle <span class=\"kw-etio\">ischémique</span>, <span class=\"kw-ci\">HTA non contrôlée</span>, <span class=\"kw-ci\">AVC ou AIT</span>, Wolff-Parkinson-White, associations dérivés ergotés/macrolides/anti-protéases ;<br>\n              <strong>Posologie :</strong> 1 unité en début de crise, à renouveler si récurrence — <span class=\"kw-chiffre\">max 2/24 h</span> ;<br>\n              <strong>Molécules PO :</strong> almotriptan, élétriptan, frovatriptan, naratriptan, rizatriptan, sumatriptan, zolmitriptan ;<br>\n              <strong>Autres voies :</strong> sumatriptan en spray nasal ou SC (non remboursé sauf indication AVF) ;<br>\n              <strong>EI :</strong> <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vertiges</span>, somnolence, <span class=\"kw-clinique\">palpitations</span>/<span class=\"kw-clinique\">tachycardie</span>, lourdeur/douleur/pression thoracique ou cou/membres, <span class=\"kw-alerte\">spasme coronaire (exceptionnel)</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Métoclopramide</strong></span></td>\n            <td>Antinausées qui soulage les troubles digestifs et améliore l'absorption des autres traitements de crise ;<br>\n              <span class=\"kw-ci\"><strong>CI :</strong></span> enfant, ATCD de dyskinésie aux neuroleptiques, phéochromocytome\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Stratégie de crise (selon intensité)</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Crise légère</strong></td><td><span class=\"kw-ttt\">AINS</span> → triptan si soulagement insuffisant à<span class=\"kw-chiffre\"> 1 h</span></td></tr>\n          <tr><td><strong>Crise modérée</strong></td><td>Triptan → <span class=\"kw-ttt\">AINS</span> si soulagement insuffisant à<span class=\"kw-chiffre\"> 1 h</span></td></tr>\n          <tr><td><strong>Crise sévère</strong></td><td><span class=\"kw-ttt\">AINS + triptan</span> d'emblée</td></tr>\n          <tr><td><strong>Crise avec aura</strong></td><td><span class=\"kw-ttt\">AINS</span> dès le début de l'aura → triptan dès le début de la <span class=\"kw-clinique\">céphalée</span></td></tr>\n          <tr><td><strong>Troubles digestifs</strong></td><td>Ajouter <span class=\"kw-ttt\">métoclopramide</span> (PO, rectal ou injectable)</td></tr>\n          <tr><td><strong>CI aux <span class=\"kw-ttt\">AINS</span></strong></td><td><span class=\"kw-ttt\">Paracétamol + métoclopramide</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Traitement de fond — Molécule</th><th>Posologie · EI · CI</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Propranolol (bêtabloquant)</strong></span><br>1ʳᵉ intention épisodique</td>\n            <td>\n              <strong>Dose :</strong> <span class=\"kw-chiffre\">20-240 mg/j</span> (moyenne <span class=\"kw-chiffre\">80 mg</span>), 2 prises/j ou 1 prise/j LP ;<br>\n              <strong>EI :</strong> <span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-ci\">intolérance</span> à l'effort, insomnie, cauchemars, <span class=\"kw-def\">dépression</span>, troubles libido ;<br>\n              <span class=\"kw-ci\"><strong>CI absolues :</strong></span> <span class=\"kw-ci\">asthme</span>, <span class=\"kw-ci\">insuffisance cardiaque</span>, BAV, <span class=\"kw-clinique\">bradycardie</span> ;<br>\n              <span class=\"kw-ci\"><strong>Précaution :</strong></span> <span class=\"kw-def\">dépression</span> ;<br>\n              <strong>Mention PDF :</strong> possible aggravation des migraines avec aura\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Métoprolol (bêtabloquant)</strong></span><br>1ʳᵉ intention épisodique</td>\n            <td><strong>Dose :</strong> <span class=\"kw-chiffre\">50-200 mg/j</span> (moyenne <span class=\"kw-chiffre\">100 mg</span>), 1 prise/j LP ; <strong>Mêmes CI que <span class=\"kw-ttt\">propranolol</span></strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Topiramate (anti-épileptique)</strong></span><br>1ʳᵉ intention chronique</td>\n            <td>\n              <strong>Dose :</strong> <span class=\"kw-chiffre\">50-200 mg/j</span> (moyenne <span class=\"kw-chiffre\">100 mg</span>), 1 ou 2 prises/j ;<br>\n              <strong>EI fréquents :</strong> <span class=\"kw-clinique\">paresthésies</span>, <span class=\"kw-clinique\">perte de poids</span>, troubles cognitifs (manque du mot), <span class=\"kw-def\">dépression</span> ;<br>\n              <strong>EI rares :</strong> <span class=\"kw-alerte\">lithiase rénale</span>, <span class=\"kw-alerte\">myopie aiguë avec glaucome à angle aigu</span> ;<br>\n              <span class=\"kw-ci\"><strong>CI absolues :</strong></span> <span class=\"kw-ci\">hypersensibilité</span>, <span class=\"kw-ci\">grossesse</span>, glaucome, prise de <span class=\"kw-ttt\">metformine</span>, <span class=\"kw-ci\">insuffisance hépatique</span> ou rénale, lithiase rénale ;<br>\n              <span class=\"kw-ci\"><strong>Précaution :</strong></span> <span class=\"kw-def\">dépression</span>, idées suicidaires\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Amitriptyline (tricyclique)</strong></span></td>\n            <td>\n              <strong>Dose :</strong> <span class=\"kw-chiffre\">10-100 mg/j</span> (moyenne <span class=\"kw-chiffre\">25 mg</span>), 1 prise au dîner ;<br>\n              <strong>EI :</strong> bouche sèche, somnolence, prise de poids, xérostomie, troubles libido ;<br>\n              <span class=\"kw-ci\"><strong>CI absolues :</strong></span> <span class=\"kw-ci\">glaucome</span>, <span class=\"kw-ci\">adénome prostatique</span> ;<br>\n              <span class=\"kw-ci\"><strong>Relative :</strong></span> <span class=\"kw-etio\">obésité</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Candésartan (ARA II)</strong></span></td>\n            <td>\n              <strong>Dose :</strong> <span class=\"kw-chiffre\">8-32 mg/j</span> (moyenne <span class=\"kw-chiffre\">16 mg</span>), 1 ou 2 prises ; <strong>∅ AMM en France</strong> ;<br>\n              <strong>EI :</strong> <span class=\"kw-clinique\">hypotension</span> orthostatique ;<br>\n              <span class=\"kw-ci\"><strong>CI absolues :</strong></span> IC, sténose artère rénale, IR sévère, <span class=\"kw-ci\">grossesse T2-T3</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Flunarizine (anticalcique)</strong></span></td>\n            <td>\n              <strong>Prescription &lt;<span class=\"kw-chiffre\"> 6 mois</span></strong> ;<br>\n              <strong>EI :</strong> somnolence, prise de poids, <span class=\"kw-def\">dépression</span>, <span class=\"kw-alerte\">syndrome parkinsonien</span> (extrapyramidal)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Anticorps anti-CGRP</strong></span><br>(érénumab, galcanezumab, fremanezumab SC ; eptinezumab IV)</td>\n            <td>\n              <strong>AMM :</strong> prophylaxie <span class=\"kw-chiffre\">≥ 8</span> j/mois + échec ≥ 2 fonds préalables, <strong>AMM SC uniquement</strong>, prescrits par neurologue, non remboursés ;<br>\n              <strong>Eptinézumab :</strong> hôpital uniquement\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Toxine botulique</strong></span></td>\n            <td>Migraine chronique uniquement ; ∅ AMM épisodique ; après échec <span class=\"kw-chiffre\">≥ 2</span> fonds classiques ; <strong>milieu hospitalier uniquement</strong></td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Règles de prise</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Initiation</strong></td><td>Débuter à <span class=\"kw-clinique\">faible dose</span>, augmenter progressivement</td></tr>\n          <tr><td><strong>Observance</strong></td><td>Capitale — privilégier <span class=\"kw-clinique\">1 prise/jour</span> si possible</td></tr>\n          <tr><td><strong>Évaluation</strong></td><td>Au <span class=\"kw-chiffre\">3ᵉ mois</span> par agenda + HIT-6</td></tr>\n          <tr><td><strong>Si efficace</strong></td><td>Poursuivre <span class=\"kw-chiffre\">6 à 18 mois</span></td></tr>\n          <tr><td><strong>Si échec</strong></td><td>1. Essayer un nouveau traitement ; 2. Après <span class=\"kw-chiffre\">échec de 2 fonds</span> = <strong>avis spécialisé</strong> (anti-CGRP, botox)</td></tr>\n          <tr><td><strong>Limite traitement de crise</strong></td><td><span class=\"kw-chiffre\">≤ 8 j/mois</span> (adulte)</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Crise rebelle / État de mal migraineux</th><th>CAT</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td>Crise &gt; <span class=\"kw-chiffre\">72 h</span> + retentissement important sur l'état général ; <span class=\"kw-alerte\">suspecter une céphalée secondaire</span></td></tr>\n          <tr><td><strong>1ʳᵉ intention</strong></td><td><span class=\"kw-ttt\">Sumatriptan SC</span> (si pas déjà 2 doses/<span class=\"kw-chiffre\">24 h</span>)</td></tr>\n          <tr><td><strong>2ᵉ — <span class=\"kw-alerte\">Hospitalisation</span></strong></td><td>Réhydratation IV + perfusion <span class=\"kw-ttt\">AINS</span> + <span class=\"kw-ttt\">métoclopramide</span></td></tr>\n          <tr><td><strong>3ᵉ — Si résistance</strong></td><td>Perfusion de tricycliques (<span class=\"kw-ttt\">amitriptyline</span>)</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th><span class=\"kw-ci\">Grossesse</span> et migraine</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Rassurer</strong></td><td>La <span class=\"kw-ci\">grossesse</span> n'aggrave pas l'<span class=\"kw-clinique\">évolution</span> ; entraîne souvent une <span class=\"kw-clinique\">rémission</span> des crises</td></tr>\n          <tr><td><strong>Crise — 1ʳᵉ intention</strong></td><td><span class=\"kw-ttt\">Paracétamol</span></td></tr>\n          <tr><td><strong>Crise — 2ᵉ intention</strong></td><td><span class=\"kw-ttt\">Sumatriptan</span> ; <span class=\"kw-ci\">AINS CI &gt; 24 SA</span> — ponctuel possible T1/T2</td></tr>\n          <tr><td><strong>Fond — 1ʳᵉ intention</strong></td><td>Non <span class=\"kw-etio\">médicamenteux</span> (TCC, relaxation)</td></tr>\n          <tr><td><strong>Fond — 2ᵉ intention</strong></td><td>Au cas par cas : <span class=\"kw-ttt\">propranolol</span> ou <span class=\"kw-ttt\">métoprolol</span> (à arrêter avant accouchement), ou <span class=\"kw-ttt\">amitriptyline</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Enfant — Migraine</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Crise PO</strong></td><td><span class=\"kw-ttt\">Ibuprofène 10 mg/kg</span> + <span class=\"kw-ttt\">paracétamol 15 mg/kg</span></td></tr>\n          <tr><td><strong>Crise — spray nasal</strong></td><td><span class=\"kw-ttt\">Sumatriptan</span> spray nasal <strong>AMM &gt;<span class=\"kw-chiffre\"> 12 ans</span></strong></td></tr>\n          <tr><td><strong>Limite</strong></td><td><span class=\"kw-chiffre\">≤ 2 j/sem</span> ou <span class=\"kw-chiffre\">≤ 6 j/mois</span></td></tr>\n          <tr><td><strong>Objectif</strong></td><td>Soulager en <span class=\"kw-chiffre\">≤ 2 h</span></td></tr>\n          <tr><td><strong>Fond — Indication</strong></td><td><span class=\"kw-chiffre\">≥ 3-4 crises/mois</span> (<span class=\"kw-chiffre\">30-40 %</span> des patients)</td></tr>\n          <tr><td><strong>Fond — 1ʳᵉ intention</strong></td><td><span class=\"kw-clinique\">Biofeedback, autohypnose, TCC</span> (souvent indisponibles en France)</td></tr>\n          <tr><td><strong>Fond — 2ᵉ intention</strong></td><td><span class=\"kw-ttt\">Amitriptyline</span>, <span class=\"kw-ttt\">propranolol</span>, <span class=\"kw-ttt\">topiramate</span>, <span class=\"kw-ttt\">flunarizine</span>, pizotifène</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>AVF — Traitement</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Mesures générales</strong></td>\n            <td>\n              Information : affection bénigne mais handicap réel, évaluer le retentissement ;<br>\n              <span class=\"kw-ci\">Éviction des FD</span> : <span class=\"kw-etio\">alcool</span> (déclenchant +++), <span class=\"kw-etio\">tabac</span> (associé<span class=\"kw-chiffre\"> 80 %</span>) ;<br>\n              <span class=\"kw-clinique\">Horaires de sommeil réguliers</span> (générateur hypothalamique)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Crise — Triptan</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Sumatriptan SC</span> (<span class=\"kw-chiffre\">6 mg</span>/mL) — disparition douleur en <span class=\"kw-chiffre\">3-10 min</span> ;<br>\n              <strong>Modalités :</strong> <span class=\"kw-chiffre\">max 2/24 h</span>, possible quotidiennement ; <span class=\"kw-ttt\">médicament d'exception</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Crise — Oxygène</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Oxygénothérapie nasale haut débit</span> au masque facial : <span class=\"kw-chiffre\">12-15 L/min × 15-20 min</span> ;<br>\n              <strong>Prescription :</strong> remboursée, mais réservée à neurologue, ORL ou centre d'algologie\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fond</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Vérapamil</span> (<span class=\"kw-ttt\">inhibiteur calcique</span>) <span class=\"kw-chiffre\">120 mg × 3-4/j, max 960 mg/j</span> ; <span class=\"kw-imagerie\">ECG préalable</span> obligatoire ;<br>\n              Méthysergide, indométacine, <span class=\"kw-ttt\">corticothérapie</span> orale (rebond à l'arrêt — prudence) ;<br>\n              Injections sous-occipitales de <span class=\"kw-ttt\">corticoïdes</span> (sans rebond) ;<br>\n              <span class=\"kw-ttt\">Carbonate de lithium</span> : formes chroniques ;<br>\n              Stimulation du grand nerf occipital, stimulation cérébrale profonde (dernier recours)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Névralgie du V — Traitement</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1ʳᵉ intention</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Carbamazépine</span> — efficacité telle qu'elle constitue un <strong>test thérapeutique</strong> ;<br>\n              <strong>Dose :</strong> <span class=\"kw-chiffre\">400-1600 mg/j</span>, 2-3 prises/j, à prendre <span class=\"kw-chiffre\">30-45 min avant les repas</span> ;<br>\n              <strong>EI sujet âgé :</strong> somnolence, <span class=\"kw-clinique\">vertiges</span>, ataxie, <span class=\"kw-clinique\">confusion</span> ;<br>\n              <span class=\"kw-imagerie\"><strong>Surveillance :</strong></span> <span class=\"kw-bio\">NFS</span> (agranulocytose), transaminases (<span class=\"kw-def\">hépatite</span>), <span class=\"kw-bio\">natrémie</span> (hyponatrémie)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Si <span class=\"kw-ci\">intolérance</span> / CI</strong></td>\n            <td><span class=\"kw-ttt\">Oxcarbamazépine</span>, <span class=\"kw-ttt\">baclofène</span> seul ou en association ; <span class=\"kw-ttt\">lamotrigine</span>, <span class=\"kw-ttt\">gabapentine</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Chirurgie</span> — Si échec</strong></td>\n            <td>\n              Choix selon âge + <span class=\"kw-imagerie\">IRM</span> :<br>\n              · <span class=\"kw-clinique\">&lt; 70 ans + conflit IRM</span> = <span class=\"kw-ttt\">décompression vasculaire microchirurgicale</span> avec Teflon® par craniotomie ;<br>\n              · <span class=\"kw-clinique\">&lt; 70 ans sans conflit IRM</span> = <span class=\"kw-ttt\">radiochirurgie GammaKnife</span> ;<br>\n              · <span class=\"kw-clinique\">&gt; 70 ans ou mauvais état général</span> = <span class=\"kw-ttt\">thermocoagulation percutanée du ganglion de Gasser</span> ou compression par ballonet\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Neuropathie trigéminale douloureuse</strong></td>\n            <td>Traitement de la douleur neuropathique focale : <span class=\"kw-ttt\">lidocaïne</span> en emplâtres, TENS, <span class=\"kw-ttt\">duloxétine</span>/<span class=\"kw-ttt\">venlafaxine</span>, <span class=\"kw-ttt\">gabapentine</span>, <span class=\"kw-ttt\">amitriptyline</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 372\" role=\"img\" aria-label=\"Arbre du choix chirurgical de la névralgie essentielle du trijumeau, en cas d'échec du traitement médical. Première question : le patient a-t-il moins de 70 ans et un bon état général. Si non, c'est-à-dire plus de 70 ans ou mauvais état général, on choisit une thermocoagulation percutanée ou une compression par ballonet du ganglion de Gasser. Si oui, deuxième question : existe-t-il un conflit vasculo-nerveux visible à l'IRM. Si oui, on choisit la décompression vasculaire microchirurgicale avec Teflon par craniotomie. Si non, on choisit la radiochirurgie GammaKnife.\" style=\"height:auto;display:block;border-radius:8px\">\n          <rect class=\"fb-grey\" x=\"120\" y=\"10\" width=\"320\" height=\"48\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"280\" y=\"31\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">Névralgie rebelle au traitement médical</text>\n          <text class=\"tx-grey\" x=\"280\" y=\"48\" text-anchor=\"middle\" font-size=\"11\">(échec carbamazépine) → indication chirurgicale</text>\n          <line class=\"ln\" x1=\"280\" y1=\"58\" x2=\"280\" y2=\"74\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,80 275,72 285,72\"/>\n\n          <rect class=\"fb-blue\" x=\"150\" y=\"82\" width=\"260\" height=\"46\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"280\" y=\"103\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">Âge &lt;<span class=\"kw-chiffre\"> 70 ans</span> + bon état général ?</text>\n          <text class=\"tx-blue\" x=\"280\" y=\"120\" text-anchor=\"middle\" font-size=\"10.5\">(1ʳᵉ question décisionnelle)</text>\n\n          <line class=\"ln\" x1=\"280\" y1=\"128\" x2=\"280\" y2=\"144\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"155\" y1=\"144\" x2=\"450\" y2=\"144\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"155\" y1=\"144\" x2=\"155\" y2=\"160\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"155,166 150,158 160,158\"/>\n          <line class=\"ln\" x1=\"450\" y1=\"144\" x2=\"450\" y2=\"282\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"450,288 445,280 455,280\"/>\n          <text class=\"tx-ok\" x=\"170\" y=\"158\" text-anchor=\"start\" font-size=\"11\" font-weight=\"700\">OUI</text>\n          <text class=\"tx-red\" x=\"445\" y=\"158\" text-anchor=\"end\" font-size=\"11\" font-weight=\"700\">NON (&gt;<span class=\"kw-chiffre\"> 70 ans</span> / mauvais EG)</text>\n\n          <rect class=\"fb-blue\" x=\"25\" y=\"168\" width=\"260\" height=\"46\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"155\" y=\"189\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">Conflit vasculo-nerveux à l'<span class=\"kw-imagerie\">IRM</span> ?</text>\n          <text class=\"tx-blue\" x=\"155\" y=\"206\" text-anchor=\"middle\" font-size=\"10.5\">(2ᵉ question décisionnelle)</text>\n\n          <line class=\"ln\" x1=\"155\" y1=\"214\" x2=\"155\" y2=\"230\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"75\" y1=\"230\" x2=\"235\" y2=\"230\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"75\" y1=\"230\" x2=\"75\" y2=\"246\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"75,252 70,244 80,244\"/>\n          <line class=\"ln\" x1=\"235\" y1=\"230\" x2=\"235\" y2=\"246\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"235,252 230,244 240,244\"/>\n          <text class=\"tx-ok\" x=\"68\" y=\"244\" text-anchor=\"start\" font-size=\"10.5\" font-weight=\"700\">OUI</text>\n          <text class=\"tx-amber\" x=\"242\" y=\"244\" text-anchor=\"start\" font-size=\"10.5\" font-weight=\"700\">NON</text>\n\n          <rect class=\"fb-ok\" x=\"10\" y=\"254\" width=\"150\" height=\"78\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"85\" y=\"276\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">Décompression</text>\n          <text class=\"tx-ok\" x=\"85\" y=\"292\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">microvasculaire</text>\n          <text class=\"tx-ok\" x=\"85\" y=\"310\" text-anchor=\"middle\" font-size=\"10\">Teflon® par</text>\n          <text class=\"tx-ok\" x=\"85\" y=\"324\" text-anchor=\"middle\" font-size=\"10\">craniotomie</text>\n\n          <rect class=\"fb-amber\" x=\"170\" y=\"254\" width=\"150\" height=\"78\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"245\" y=\"284\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">Radiochirurgie</text>\n          <text class=\"tx-amber\" x=\"245\" y=\"302\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">GammaKnife</text>\n\n          <rect class=\"fb-red\" x=\"375\" y=\"290\" width=\"175\" height=\"72\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"462\" y=\"312\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">Thermocoagulation</text>\n          <text class=\"tx-red\" x=\"462\" y=\"328\" text-anchor=\"middle\" font-size=\"10\">ou compression par</text>\n          <text class=\"tx-red\" x=\"462\" y=\"342\" text-anchor=\"middle\" font-size=\"10\">ballonet — ganglion</text>\n          <text class=\"tx-red\" x=\"462\" y=\"356\" text-anchor=\"middle\" font-size=\"10\">de Gasser (percutané)</text>\n        </svg>\n        <figcaption>Choix chirurgical de la névralgie essentielle du trijumeau (si échec du traitement médical), selon l'âge/état général puis le conflit vasculo-nerveux à l'<span class=\"kw-imagerie\">IRM</span>. Source : fiche source EDN item 99 — Névralgies faciales et crâniennes.</figcaption>\n      </figure>\n      <div class=\"callout callout-warn\"><strong>Stratégies pour améliorer un traitement de crise insuffisant.</strong>\n        <ul>\n          <li>Traiter le plus précocement possible</li>\n          <li>Augmenter si possible la dose d'<span class=\"kw-ttt\">AINS</span> et/ou de triptan</li>\n          <li>Changer pour une forme non orale (suppositoire <span class=\"kw-ttt\">AINS</span>/<span class=\"kw-ttt\">métoclopramide</span>, sumatriptan spray nasal ou SC)</li>\n          <li>Changer d'<span class=\"kw-ttt\">AINS</span> et/ou de triptan</li>\n          <li>Combiner <span class=\"kw-ttt\">AINS + triptan + métoclopramide</span> pour les crises sévères</li>\n        </ul>\n        <p><strong>Résistance :</strong> inefficacité de <span class=\"kw-chiffre\">≥ 2</span> <span class=\"kw-ttt\">AINS</span> ou ≥ 2 triptans, à la bonne dose et par la bonne voie, sur ≥ 3 crises.</p>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p>","frequence":0},{"id":"99-16","rang":"A","rubrique":"Prise en charge","titre":"Savoir conseiller un patient migraineux","contenu":"<p>Le conseil au migraineux porte sur <span class=\"kw-def\">hygiène de vie</span>, <span class=\"kw-def\">gestion des FD</span>, <span class=\"kw-def\">contraception</span>, <span class=\"kw-def\">limite du traitement de crise</span> et <span class=\"kw-def\">comorbidités psychiatriques</span>. Objectif : optimiser la qualité de vie et prévenir la chronicisation.</p>\n      <table >\n        <thead><tr><th>Hygiène de vie</th><th>Recommandation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Sommeil</strong></td><td>Horaires réguliers, durée suffisante — éviter manque et excès</td></tr>\n          <tr><td><strong>Alimentation</strong></td><td>Repas équilibrés et réguliers ; <span class=\"kw-ci\">éviter les régimes restrictifs draconiens</span> qui altèrent la qualité de vie sans bénéfice prouvé</td></tr>\n          <tr><td><strong>Hydratation</strong></td><td>Optimale</td></tr>\n          <tr>\n            <td><strong>Activité physique</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Endurance</span> : marche rapide, vélo, course ;<br>\n              <strong>Recos OMS :</strong> <span class=\"kw-chiffre\">2 h 30/semaine</span> d'activité d'endurance ;<br>\n              Efficacité démontrée dans la prévention des migraines\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Gestion des FD</th><th>Stratégie</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">Agenda des céphalées</span></strong></td><td>Outil de <span class=\"kw-def\">suivi</span> <strong>obligatoire</strong> — fréquence, sévérité, traitements, FD identifiables ; base de l'évaluation à <span class=\"kw-chiffre\">3 mois</span></td></tr>\n          <tr><td><strong>Coping (enfant ++)</strong></td><td>Apprendre à gérer la situation en présence du facteur déclenchant — alternative à l'éviction</td></tr>\n          <tr><td><strong>Comportements <span class=\"kw-ci\">à éviter</span></strong></td><td><span class=\"kw-ci\">Éviction draconienne des FD</span> (régimes restrictifs) — perte de qualité de vie sans bénéfice</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Contraception — Migraine SANS aura</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Absence de FR artériel</strong></td><td>Toutes les contraceptions possibles, y compris COP</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">≥ 1</span> FR artériel</strong></td><td><span class=\"kw-ci\">COP contre-indiquée</span> — progestatifs purs et autres moyens possibles</td></tr>\n          <tr><td><strong>Notes</strong></td><td>La COP exerce une influence variable (peut ↑ ou ↓ la fréquence des crises) ; contraception continue possible si crises cataméniales</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Contraception — Migraine AVEC aura</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>COP</strong></td>\n            <td><span class=\"kw-ci\"><strong>CONTRE-INDIQUÉE (absolue, HAS 2019)</strong></span> chez la femme migraineuse avec aura — surrisque <span class=\"kw-alerte\">AVC ischémique</span></td>\n          </tr>\n          <tr><td><strong>Contraception privilégiée</strong></td><td><span class=\"kw-ttt\">Progestatif pur</span> ou autre moyen non hormonal</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Message clé contraception.</strong> Devant toute migraineuse, <strong>distinguer MSA et MA</strong> : la migraine avec aura <span class=\"kw-ci\">interdit</span> absolument la COP (surrisque d'<span class=\"kw-def\">AVC</span> <span class=\"kw-etio\">ischémique</span> chez la femme &lt;<span class=\"kw-chiffre\"> 45 ans</span> tabagique). Switch obligatoire vers progestatif pur ou autre moyen.</div>\n      <table >\n        <thead><tr><th>Limite du traitement de crise</th><th>Cible</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Adulte</strong></td><td><span class=\"kw-chiffre\">≤ 8 j/mois</span></td></tr>\n          <tr><td><strong>Enfant</strong></td><td><span class=\"kw-chiffre\">≤ 2 j/sem</span> ou <span class=\"kw-chiffre\">≤ 6 j/mois</span></td></tr>\n          <tr><td><strong>Triptans/<span class=\"kw-ttt\">opiacés</span></strong></td><td>Surconsommation à partir de <span class=\"kw-chiffre\">≥ 10 j/mois</span> &gt;<span class=\"kw-chiffre\"> 3 mois</span> = CAM (cf. obj-12)</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Suivi</span> & <span class=\"kw-def\">dépistage</span></th><th>Outils</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Retentissement</strong></td><td><span class=\"kw-bio\">HIT-6</span> (Headache Impact Test) — seuil <span class=\"kw-chiffre\">≥ 60</span> = migraine sévère</td></tr>\n          <tr><td><strong>Fréquence / FD</strong></td><td><span class=\"kw-bio\">Agenda des céphalées</span> à chaque consultation</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Comorbidités</span> psy</strong></td><td><span class=\"kw-bio\">Échelle HAD</span> à chaque consultation — <span class=\"kw-alerte\">FR de chronicisation</span> majeur</td></tr>\n          <tr><td><strong>Anxiété / <span class=\"kw-def\">dépression</span></strong></td><td>Fréquentes chez les migraineux — à prendre en charge ; ne pas sous-estimer</td></tr>\n          <tr><td><strong>Traitements psycho-comportementaux</strong></td><td>Relaxation, biofeedback, TCC — pour les <span class=\"kw-def\">comorbidités</span> psy ; pas d'efficacité prouvée sur la migraine elle-même</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Traitements non <span class=\"kw-etio\">médicamenteux</span></th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Neuromodulation non invasive</strong></td><td>Efficacité démontrée — appareillages non remboursés</td></tr>\n          <tr><td><strong>Exercice physique d'endurance</strong></td><td><span class=\"kw-chiffre\">2 h 30/semaine</span> (marche rapide, vélo, course) — efficacité prouvée (recos OMS)</td></tr>\n          <tr><td><strong>Acupuncture</strong></td><td>Efficace en prévention à court terme — alternative ou complément</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p>","frequence":0},{"id":"99-17","rang":"B","rubrique":"Contenu multimédia","titre":"A partir d'une vidéo d'interrogatoire, évoquer le diagnostic de migraine, d'algie vasculaire de la face, de névralgie du trijumeau","contenu":"<div class=\"callout callout-warn\"><strong>À compléter.</strong> Aucune vidéo d'interrogatoire n'a été fournie dans les fiches sources du dossier <code>99-migraine-av-nt/</code>. Kevin enrichira cet objectif manuellement (Pilly, Collège CEN, Asclépia ou autre source vidéo) le moment venu.</div>\n      <p>En attendant la vidéo, voici la <strong>grille de discrimination clinique</strong> des 3 entités à partir des éléments d'interrogatoire (à utiliser comme support de révision) :</p>\n      <table >\n        <thead>\n          <tr>\n            <th>Élément d'interrogatoire</th>\n            <th>Migraine</th>\n            <th><span class=\"kw-etio\">AVF</span></th>\n            <th><span class=\"kw-etio\">Névralgie du V</span></th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Latéralité</strong></td>\n            <td><span class=\"kw-clinique\">Unilatérale à bascule</span></td>\n            <td><span class=\"kw-clinique\">Unilatérale STRICTE</span></td>\n            <td><span class=\"kw-clinique\">Unilatérale</span> (territoire V)</td>\n          </tr>\n          <tr>\n            <td><strong>Durée d'une crise</strong></td>\n            <td><span class=\"kw-chiffre\">4 à 72 h</span></td>\n            <td><span class=\"kw-chiffre\">15 à 180 min</span> (acmé<span class=\"kw-chiffre\"> 10-15 min</span>)</td>\n            <td>Salves <span class=\"kw-chiffre\">≤ 2 min</span></td>\n          </tr>\n          <tr>\n            <td><strong>Caractère</strong></td>\n            <td><span class=\"kw-clinique\">Pulsatile</span></td>\n            <td><span class=\"kw-clinique\">Broiement / arrachement</span></td>\n            <td><span class=\"kw-clinique\">Éclair / décharge électrique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Topographie</strong></td>\n            <td>Frontale, orbitaire, temporale, occipitale</td>\n            <td>Péri-orbitaire (point de départ), orbitaire, sus-orbitaire, temporale</td>\n            <td>Territoire <span class=\"kw-clinique\">V2</span> (<span class=\"kw-chiffre\">40 %</span>) &gt; V3 &gt; V1</td>\n          </tr>\n          <tr>\n            <td><strong>Fréquence</strong></td>\n            <td>Variable selon les patients</td>\n            <td><span class=\"kw-chiffre\">0,5-8/jour</span> en période active</td>\n            <td><span class=\"kw-chiffre\">5-10 salves/jour</span></td>\n          </tr>\n          <tr>\n            <td><strong>Facteur déclenchant</strong></td>\n            <td>FD multiples (hormones, stress, sommeil, <span class=\"kw-etio\">alcool</span>, climat…)</td>\n            <td><span class=\"kw-etio\">Alcool</span>, cycle circadien (horaires fixes), circannuel</td>\n            <td><span class=\"kw-clinique\">Zone gâchette</span> (brossage, parole, mastication)</td>\n          </tr>\n          <tr>\n            <td><strong>Signes associés</strong></td>\n            <td><span class=\"kw-clinique\">Nausées</span> ± <span class=\"kw-clinique\">vomissements</span> ; <span class=\"kw-clinique\">photo + phonophobie</span> ; calmée par repos/obscurité</td>\n            <td><span class=\"kw-clinique\">Dysautonomiques homolatéraux</span> (larmoiement, injection, rhinorrhée, ptosis/myosis) + <span class=\"kw-clinique\">agitation</span></td>\n            <td><span class=\"kw-clinique\">Aucun</span> ; patient s'immobilise brièvement</td>\n          </tr>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td>Normal</td>\n            <td>Normal sauf CBH partiel possible</td>\n            <td>Normal (anormal = <span class=\"kw-alerte\">drapeau rouge</span> → cause secondaire)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td><span class=\"kw-chiffre\">3F/1H</span>,<span class=\"kw-chiffre\"> 30-50 ans</span>, ATCD familiaux fréquents</td>\n            <td><span class=\"kw-chiffre\">5H/1F</span>, ~<span class=\"kw-chiffre\">30 ans</span>, <span class=\"kw-etio\">tabac 80 %</span></td>\n            <td><span class=\"kw-chiffre\">3F/2H</span>, &gt;<span class=\"kw-chiffre\"> 50-60 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Traitement de crise</strong></td>\n            <td><span class=\"kw-ttt\">AINS + triptan</span> ± <span class=\"kw-ttt\">métoclopramide</span></td>\n            <td><span class=\"kw-ttt\">Sumatriptan SC</span> + <span class=\"kw-ttt\">O₂ haut débit</span></td>\n            <td><span class=\"kw-ttt\">Carbamazépine</span> (fond — pas de traitement de crise propre)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Pattern recognition rapide.</strong>\n        <ul>\n          <li><strong>Femme <span class=\"kw-chiffre\">30 ans</span>, crises de <span class=\"kw-chiffre\">24 h</span>, pulsatile, <span class=\"kw-clinique\">nausées</span>, calmée par obscurité, ATCD familiaux</strong> → migraine</li>\n          <li><strong>Homme <span class=\"kw-chiffre\">30 ans</span>, fumeur, crises de <span class=\"kw-chiffre\">1 h</span> péri-orbitaires unilatérales strictes avec larmoiement et agitation, à horaires fixes</strong> → AVF</li>\n          <li><strong>Femme <span class=\"kw-chiffre\">65 ans</span>, salves de quelques secondes en éclair sur la pommette droite (V2), déclenchées par le brossage des dents</strong> → névralgie du V</li>\n        </ul>\n      </div>","frequence":0}],"astuces":[{"type":"danger","titre":"Drapeaux rouges SNOOP4 — à connaître par cœur","contenu":"<strong>S</strong>ystemic (fièvre, AEG, cancer, VIH) · <strong>N</strong>eurological (focal, confusion, œdème papillaire) · <strong>O</strong>nset sudden (coup de tonnerre → HSA) · <strong>O</strong>lder (&gt; 50 ans, 1ʳᵉ céphalée → Horton) · <strong>P</strong>attern change / <strong>P</strong>ostural / <strong>P</strong>recipitated by Valsalva / <strong>P</strong>regnancy. Tout drapeau = imagerie cérébrale en urgence."},{"type":"info","titre":"Migraine vs AVF vs NT — distinguer en 3 critères","contenu":"<strong>Migraine :</strong> hémicrânienne pulsatile, 4–72 h, photo/phonophobie, patient au calme dans le noir. <strong>AVF :</strong> orbitaire unilatérale ultra-violente, 15–180 min, signes dysautonomiques (larmoiement, rhinorrhée, Horner), patient agité qui déambule. <strong>NT :</strong> éclair fulgurant de quelques secondes, zones gâchettes, V2/V3, intervalle libre asymptomatique."},{"type":"warn","titre":"Triptans — contre-indications cardio-vasculaires à connaître","contenu":"<strong>CI absolues :</strong> coronaropathie, IDM, AVC/AIT, AOMI, HTA non contrôlée, Raynaud sévère, migraine hémiplégique ou basilaire, association IMAO/ergotés. Mécanisme : agonistes 5-HT1B/1D = vasoconstriction. Si triptans CI → gépants ou ditans."},{"type":"danger","titre":"Céphalée par abus médicamenteux (CAM) — le piège classique","contenu":"CCQ sous traitement quotidien : céphalée ≥ <strong>15 j/mois</strong> + antalgique ≥ <strong>10 j/mois</strong> (triptans, opioïdes, combinés) ou ≥ <strong>15 j/mois</strong> (AINS, paracétamol seul). Traitement = <strong>sevrage</strong> + traitement de fond + soutien. Le piège : augmenter les antalgiques aggrave la situation."},{"type":"info","titre":"AVF — l'oxygène à haut débit, traitement gratuit et puissant","contenu":"<strong>O₂ 100 % à 12–15 L/min</strong> au masque pendant 15–20 min stoppe la crise dans 70 % des cas, sans CI ni effet rebond. À prescrire systématiquement avec concentrateur à domicile + sumatriptan injectable SC 6 mg."},{"type":"warn","titre":"Migraine avec aura + œstroprogestatifs = CI absolue","contenu":"Risque d'AVC ischémique multiplié par 2 à 4. Toute femme migraineuse avec aura doit avoir une contraception <strong>progestative seule</strong> (DIU, implant, micropilule) ou non hormonale. Migraine sans aura : œstroprogestatifs possibles si pas d'autres FdR CV."},{"type":"info","titre":"Otalgie à examen otoscopique normal chez un fumeur > 50 ans","contenu":"Toujours évoquer une <strong>otalgie réflexe</strong> d'origine pharyngo-laryngée = cancer ORL jusqu'à preuve du contraire. Indication formelle de nasofibroscopie + panendoscopie ORL."}],"strategie":{"urgence":"<p><strong>État de mal migraineux <span class=\"q\">— et crise rebelle (rang C)</span></strong></p><p>1. <span class=\"kw-ttt\">Sumatriptan SC</span> (si &lt; 2 doses de triptan en <span class=\"kw-chiffre\">24h</span>) · 2. <span class=\"kw-ttt\">réhydratation IV</span> + <span class=\"kw-ttt\">AINS IV</span> + <span class=\"kw-ttt\">métoclopramide</span> · 3. <span class=\"kw-ttt\">amitriptyline</span> IV</p><ul><li><span class=\"kw-def\">État de mal migraineux</span> = crise <span class=\"kw-chiffre\">&gt; 72h</span> avec retentissement important sur l'état général</li><li><span class=\"kw-def\">Crise rebelle</span> = ne répond pas au traitement usuel per os</li><li>Dans les 2 cas → <span class=\"kw-alerte\">suspecter une céphalée secondaire</span></li></ul><p><strong>Crise d'algie vasculaire de la face <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> <span class=\"kw-ttt\">antalgique</span></span></strong></p><p><span class=\"kw-ttt\">Sumatriptan SC</span> (soulagement en <span class=\"kw-chiffre\">3-10 min</span>) + <span class=\"kw-ttt\">oxygénothérapie</span> haut débit <span class=\"kw-chiffre\">12-15 L/min</span> pendant <span class=\"kw-chiffre\">15-20 min</span> au masque</p><ul><li>Douleur <span class=\"kw-clinique\">sévère à très sévère</span>, acmé en <span class=\"kw-chiffre\">10-15 min</span>, <span class=\"kw-clinique\">agitation</span></li><li>Traitement de crise à action très rapide indispensable</li></ul>","hospit":"<p><strong>Migraine</strong></p><p><span class=\"kw-ttt\">Anticorps anti-CGRP</span> prescrits par le neurologue uniquement ; <span class=\"kw-ttt\">eptinézumab IV</span> et <span class=\"kw-ttt\">toxine botulique</span> en milieu hospitalier</p><ul><li>Prise en charge <span class=\"kw-clinique\">ambulatoire</span> ; pas d'<span class=\"kw-alerte\">hospitalisation</span> en règle</li><li>Avis <span class=\"kw-def\">neurologue</span> après échec de <span class=\"kw-chiffre\">≥ 2</span> traitements de fond</li></ul><p><strong>Algie vasculaire de la face</strong></p><p><span class=\"kw-ttt\">Oxygénothérapie</span> prescrite seulement par neurologue / ORL / centre d'algologie ; formes chroniques pharmacorésistantes → avis d'une équipe spécialisée multidisciplinaire</p><ul><li>Prise en charge <span class=\"kw-clinique\">ambulatoire</span></li><li><span class=\"kw-ttt\">Sumatriptan SC</span> = ordonnance de médicament d'exception</li></ul><p><strong>Névralgie du trijumeau</strong></p><p>Avis <span class=\"kw-def\">neurochirurgical</span> si échec médical (décompression vasculaire, radiochirurgie, thermocoagulation)</p><ul><li>Traitement <span class=\"kw-ttt\">médical</span> ambulatoire en 1ʳᵉ intention</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Céphalée en coup de tonnerre</span> / début brutal → <span class=\"kw-imagerie\">imagerie cérébrale</span> en <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-alerte\">Céphalée récente s'aggravant</span> depuis <span class=\"kw-chiffre\">&lt; 7 jours</span> → <span class=\"kw-imagerie\">imagerie</span> en <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-clinique\">Fièvre</span>, <span class=\"kw-alerte\">signes neurologiques focaux</span>, <span class=\"kw-etio\">immunodépression</span> ou suspicion d'<span class=\"kw-etio\">intoxication au CO</span> → <span class=\"kw-imagerie\">imagerie</span> en <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-alerte\">1ʳᵉ céphalée après 50 ans</span> ou changement de la <span class=\"kw-clinique\">céphalée</span> habituelle → céphalée secondaire</li><li><span class=\"kw-clinique\">Algie faciale unilatérale aiguë</span> + <span class=\"kw-alerte\">Claude Bernard-Horner</span> → <span class=\"kw-etio\">dissection carotidienne</span> (<span class=\"kw-alerte\">AVC</span> du sujet jeune)</li><li><span class=\"kw-clinique\">Claudication de la mâchoire</span>, douleur de la langue/du nez (sujet <span class=\"kw-chiffre\">&gt; 50 ans</span>) → <span class=\"kw-etio\">artérite temporale (Horton)</span></li><li><span class=\"kw-clinique\">Anesthésie de la houppe du menton</span> (neuropathie mentonnière) → <span class=\"kw-etio\">tumeur maligne</span></li><li>Névralgie du trijumeau <span class=\"kw-alerte\">atypique</span> (sujet jeune, territoire V1, fond douloureux permanent, hypoesthésie, atteinte des 3 territoires, examen anormal) → forme <span class=\"kw-etio\">symptomatique</span> (SEP, zona, tumeur)</li></ul>","principes":"<p><strong>Règle d'or :</strong> distinguer le <span class=\"kw-def\">traitement de crise</span> (soulager la crise en cours) du <span class=\"kw-def\">traitement de fond</span> (réduire fréquence et sévérité) ; aucun ne fait disparaître les crises. Limiter le traitement de crise à <span class=\"kw-chiffre\">≤ 8 jours/mois</span> (risque de <span class=\"kw-alerte\">céphalée par abus médicamenteux</span>).</p><p><strong>Migraine — traitement de crise</strong></p><ul><li>Forme modérée : <span class=\"kw-ttt\">AINS</span> (<span class=\"kw-ttt\">ibuprofène</span>, <span class=\"kw-ttt\">kétoprofène</span>), <span class=\"kw-ttt\">aspirine</span>, <span class=\"kw-ttt\">paracétamol</span></li><li>Forme intense : <span class=\"kw-ttt\">triptans</span> per os (les plus efficaces) ; <span class=\"kw-ttt\">métoclopramide</span> si troubles digestifs</li><li>Triptans <span class=\"kw-ci\">contre-indiqués si ATCD vasculaires</span> (coronaropathie, <span class=\"kw-alerte\">AVC</span>/<span class=\"kw-alerte\">AIT</span>, <span class=\"kw-etio\">HTA</span> non contrôlée, AOMI)</li><li>Éviter les <span class=\"kw-ci\">opioïdes de palier 2-3</span> et la <span class=\"kw-ci\">caféine</span> (risque d'abus)</li><li>Stratégie de crise selon aura et intensité → voir l'arbre décisionnel ci-dessous</li></ul><p><strong>Migraine — traitement de fond</strong></p><ul><li>Indiqué si traitement de crise <span class=\"kw-chiffre\">≥ 8 j/mois</span>, migraine sévère/chronique, <span class=\"kw-def\">HIT-6</span> <span class=\"kw-chiffre\">≥ 60</span> ou crises invalidantes</li><li>1ʳᵉ intention : <span class=\"kw-ttt\">propranolol</span> / <span class=\"kw-ttt\">métoprolol</span> (épisodique), <span class=\"kw-ttt\">topiramate</span> (chronique)</li><li>Échec de <span class=\"kw-chiffre\">2</span> traitements de fond → avis spécialisé (<span class=\"kw-ttt\">anti-CGRP</span>, <span class=\"kw-ttt\">toxine botulique</span>)</li><li><span class=\"kw-ci\">Valproate</span> et <span class=\"kw-ci\">topiramate</span> tératogènes : <span class=\"kw-ci\">à éviter</span> chez la femme en âge de procréer</li></ul><p><strong>Algie vasculaire de la face</strong></p><ul><li>Crise : <span class=\"kw-ttt\">sumatriptan SC</span> + <span class=\"kw-ttt\">oxygénothérapie</span> haut débit</li><li>Fond (crises pluriquotidiennes, formes longues/chroniques) : <span class=\"kw-ttt\">vérapamil</span> (<span class=\"kw-bio\">ECG</span> préalable +++), <span class=\"kw-ttt\">corticothérapie</span>, <span class=\"kw-ttt\">infiltration</span> du grand nerf occipital</li><li>Éviter les facteurs favorisants : <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">tabac</span> ; horaires de sommeil réguliers</li></ul><p><strong>Névralgie du trijumeau</strong></p><ul><li>1ʳᵉ intention : <span class=\"kw-ttt\">carbamazépine</span> (efficacité = test thérapeutique)</li><li>Échec → <span class=\"kw-ttt\">chirurgie</span> : <span class=\"kw-ttt\">décompression vasculaire</span> (conflit à l'<span class=\"kw-imagerie\">IRM</span>, <span class=\"kw-chiffre\">&lt; 70 ans</span>), <span class=\"kw-ttt\">radiochirurgie</span> ou <span class=\"kw-ttt\">thermocoagulation</span> du ganglion de Gasser (<span class=\"kw-chiffre\">&gt; 70 ans</span> / mauvais état général)</li></ul><p><strong>Contraception chez la migraineuse</strong></p><ul><li>Migraine <span class=\"kw-alerte\">avec aura</span> : <span class=\"kw-ci\">contraception œstroprogestative contre-indiquée</span> → progestatif pur ou autre moyen</li><li>Migraine <span class=\"kw-def\">sans aura</span> : <span class=\"kw-ttt\">COP</span> possible si pas de FR artériel ; si <span class=\"kw-chiffre\">≥ 1</span> FR artériel → <span class=\"kw-ci\">COP contre-indiqués</span></li></ul>","suivi":"<p><strong>Migraine = maladie chronique :</strong> <span class=\"kw-def\">suivi</span> par <span class=\"kw-def\">agenda des céphalées</span> + échelle <span class=\"kw-def\">HIT-6</span>, avec prévention de la chronicisation et de l'abus <span class=\"kw-etio\">médicamenteux</span>.</p><p><strong>Évaluation de l'impact</strong></p><ul><li>Outils : <span class=\"kw-def\">HIT-6</span> (Headache Impact Test) + <span class=\"kw-def\">agenda des céphalées</span></li><li>Migraine sévère = <span class=\"kw-chiffre\">≥ 8 j/mois</span>, <span class=\"kw-def\">HIT-6</span> <span class=\"kw-chiffre\">≥ 60</span>, interruption complète des activités dans <span class=\"kw-chiffre\">&gt; 50 %</span> des cas</li></ul><p><strong><span class=\"kw-def\">Suivi</span> du traitement</strong></p><ul><li>Traitement de crise : visite de <span class=\"kw-def\">suivi</span> à <span class=\"kw-chiffre\">2-3 mois</span> (efficacité, tolérance, abus)</li><li>Traitement de fond : efficacité jugée au <span class=\"kw-chiffre\">3ᵉ mois</span> (agenda + HIT-6)</li><li>Objectif : <span class=\"kw-chiffre\">−50 %</span> de jours de <span class=\"kw-clinique\">céphalée</span> (épisodique), <span class=\"kw-chiffre\">−30 %</span> (chronique) ; si efficace, poursuivre <span class=\"kw-chiffre\">6 à 18 mois</span></li></ul><p><strong>Prévention de la chronicisation</strong></p><ul><li>Dépister la fréquence élevée des crises (<span class=\"kw-def\">agenda</span>) et la <span class=\"kw-clinique\">dépression</span> (échelle <span class=\"kw-def\">HAD</span>)</li><li>Limiter le traitement de crise à <span class=\"kw-chiffre\">≤ 8 j/mois</span></li><li><span class=\"kw-ttt\">RHD</span> : <span class=\"kw-clinique\">sommeil</span> et repas réguliers, hydratation, activité d'<span class=\"kw-clinique\">endurance</span> <span class=\"kw-chiffre\">2h30/semaine</span> ; ne pas surévaluer les facteurs déclenchants</li></ul><p><strong><span class=\"kw-def\">Surveillance</span> des traitements de fond</strong></p><ul><li><span class=\"kw-ttt\">Carbamazépine</span> (névralgie du V) : <span class=\"kw-bio\">NFS</span> (agranulocytose), <span class=\"kw-bio\">transaminases</span> (hépatite), <span class=\"kw-bio\">natrémie</span> (hyponatrémie)</li><li><span class=\"kw-ttt\">Vérapamil</span> (AVF) : <span class=\"kw-bio\">ECG</span> avant l'instauration</li></ul>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/migraine-nevralgie-du-trijumeau-et-algies-de-la-face","label":"Collège CEN — Migraine, névralgie du trijumeau & algies de la face"},{"href":"https://www.cen-neurologie.fr/second-cycle/cephalee-inhabituelle-aigue-et-chronique-chez-ladulte-et-lenfant","label":"Collège CEN — Céphalée inhabituelle"},{"href":"https://campus.neurochirurgie.fr/article1715.html","label":"Campus Neurochirurgie — Névralgie du trijumeau"},{"href":"https://www.chu-caen.fr/wp-content/uploads/2022/12/Fiche-dinformation-nevralgie-dArnold.pdf","label":"CHU Caen — Névralgie d'Arnold (PDF patient)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Crise de migraine — Prise la plus précoce possible (<span class=\"kw-chiffre\">< 1</span>h après le début de la <span class=\"kw-clinique\">céphalée</span>) · <span class=\"kw-ttt\">AINS</span> + triptan sur la même ordonnance · ne pas dépasser <span class=\"kw-chiffre\">8 jours</span> de prise/mois · métoclopramide si troubles digestifs · paracétamol + métoclopramide si CI aux AINS","detail":"<h4>Crise de migraine — stratégie de traitement de crise — Choix selon la présence d'une aura et l'intensité de la crise</h4>","branches":[{"to":"t-aura","label":"Crise précédée d'une aura","color":"blue"},{"to":"q-intensite","label":"Pas d'aura","color":"blue"}]},{"id":"t-aura","kind":"terminal","label":"Crise avec aura","color":"blue","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">AINS</span> dès le début de l'aura</li><li><span class=\"kw-ttt\">Triptan</span> dès le début de la <span class=\"kw-clinique\">céphalée</span></li></ul><h4>À savoir</h4><ul><li>Le <span class=\"kw-ttt\">triptan</span> n'écourte pas l'aura ; ne pas le prendre pendant l'aura isolée</li></ul>"},{"id":"q-intensite","kind":"decision","label":"Intensité de la céphalée ? — Auto-évaluation par le patient ; conditionne l'ordre de prise des traitements","branches":[{"to":"t-legere","label":"Légère","color":"green"},{"to":"t-moderee","label":"Modérée","color":"amber"},{"to":"t-severe","label":"Sévère","color":"amber"}]},{"id":"t-legere","kind":"terminal","label":"Crise légère","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">AINS</span> (<span class=\"kw-ttt\">ibuprofène</span>, <span class=\"kw-ttt\">kétoprofène</span>, <span class=\"kw-ttt\">aspirine</span>) ou <span class=\"kw-ttt\">paracétamol</span> en 1ᵉ</li><li>Ajouter un <span class=\"kw-ttt\">triptan</span> si soulagement insuffisant à <span class=\"kw-chiffre\">1h</span></li></ul>"},{"id":"t-moderee","kind":"terminal","label":"Crise modérée","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Triptan</span> per os en 1ᵉ</li><li>Ajouter un <span class=\"kw-ttt\">AINS</span> si soulagement insuffisant à <span class=\"kw-chiffre\">1h</span></li></ul>"},{"id":"t-severe","kind":"terminal","label":"Crise sévère","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">AINS</span> + <span class=\"kw-ttt\">triptan</span> d'emblée, en même temps</li></ul><h4>Mesures associées</h4><ul><li><span class=\"kw-ttt\">Métoclopramide</span> si troubles digestifs ; en cas d'échec répété → évoquer une crise rebelle / un <span class=\"kw-alerte\">état de mal migraineux</span></li></ul>"}]},"cards":[]};